insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('398260a4-b7ec-5643-bf91-f8152492f34f', 'c2c5f8e5-9d00-515b-a075-ec8060385a3e', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$Paul describes people apart from Christ as spiritually dead because of sin. He is not saying they are physically dead or unable to show kindness. He means that sin has broken humanity’s relationship with God and that people cannot create spiritual life for themselves.$gs$),
  ('45523cde-a6e9-5435-ae18-bce6c8a8a058', 'c2c5f8e5-9d00-515b-a075-ec8060385a3e', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$Ephesians 2 continues with the good news: God is rich in mercy and makes people alive with Christ. Salvation begins with God’s grace, not human achievement. This diagnosis should produce humility and gratitude, not contempt for people who do not yet believe.$gs$),
  ('f29de31d-4964-5ae3-9e00-ecec91bd1aa9', 'c2c5f8e5-9d00-515b-a075-ec8060385a3e', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
insert into public.p2p_reflection_questions (id, lesson_id, question, display_order) values
  ('2891495e-100f-5cbd-bf40-ba2c03b8675d', 'c2c5f8e5-9d00-515b-a075-ec8060385a3e', $gs$In your own words, what is the main point of “Dead in Trespasses and Sins”?$gs$, 1),
  ('466ce331-107c-5b6a-bc48-c9dca814729b', 'c2c5f8e5-9d00-515b-a075-ec8060385a3e', $gs$What part of this teaching is easiest for you to understand, and what part would you like to discuss further?$gs$, 2),
  ('a2565eb6-2094-5cc2-846a-911127547b36', 'c2c5f8e5-9d00-515b-a075-ec8060385a3e', $gs$How could this truth shape one attitude or action in your life this week?$gs$, 3)
insert into public.p2p_assignments (id, lesson_id, title, instructions)
insert into public.p2p_assignment_questions (id, assignment_id, question, display_order) values
  ('34faae48-5de2-5362-a8f5-72d9652b04a5', '81081d51-26ff-5dc5-9f39-5ffb8f9fd4f4', $gs$Define the main idea in the lesson “Dead in Trespasses and Sins” using simple language.$gs$, 1),
  ('ceb4499b-5833-5771-853e-be62b3e3f254', '81081d51-26ff-5dc5-9f39-5ffb8f9fd4f4', $gs$What does the key Bible passage teach about God, people, or the Christian life?$gs$, 2),
  ('9105338d-d9e8-5989-9b4b-1bda9c1f538b', '81081d51-26ff-5dc5-9f39-5ffb8f9fd4f4', $gs$Explain why this teaching matters. Give one reason from the lesson.$gs$, 3),
  ('0e7cc851-f659-51d5-a3ad-964be8e00660', '81081d51-26ff-5dc5-9f39-5ffb8f9fd4f4', $gs$Give one practical example of how someone could respond to this teaching.$gs$, 4)
insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('633fd79a-fa5f-5bf3-ab36-e143b8a89113', 'c2c5f8e5-9d00-515b-a075-ec8060385a3e', 'memory_verse', $gs${"reference":"Ephesians 2:1","text":"And you He made alive, who were dead in trespasses and sins.","translation":""}$gs$::jsonb, 0, true, false),
  ('cfa46fee-d29b-5ec2-8d5c-6e2e849eabdf', 'c2c5f8e5-9d00-515b-a075-ec8060385a3e', 'paragraph', $gs${"text":"Definition and simple explanation\n\nPaul describes people apart from Christ as spiritually dead because of sin. He is not saying they are physically dead or unable to show kindness. He means that sin has broken humanity’s relationship with God and that people cannot create spiritual life for themselves."}$gs$::jsonb, 1, false, false),
  ('ccbf4e93-96df-51a7-9c55-cfa7dab85b98', 'c2c5f8e5-9d00-515b-a075-ec8060385a3e', 'paragraph', $gs${"text":"What this means and why it matters\n\nEphesians 2 continues with the good news: God is rich in mercy and makes people alive with Christ. Salvation begins with God’s grace, not human achievement. This diagnosis should produce humility and gratitude, not contempt for people who do not yet believe."}$gs$::jsonb, 2, false, false),
  ('40442936-4c7d-5066-9743-46be9a235cb2', 'c2c5f8e5-9d00-515b-a075-ec8060385a3e', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('0ebf42a5-881d-57c8-a355-faca2e94a5c0', 'c2c5f8e5-9d00-515b-a075-ec8060385a3e', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('223c8e83-808c-5211-9d1f-90916ef2e039', 'c2c5f8e5-9d00-515b-a075-ec8060385a3e', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Dead in Trespasses and Sins”?"}$gs$::jsonb, 5, true, true),
  ('2733ece3-dff5-5783-bda4-528e3ee1b443', 'c2c5f8e5-9d00-515b-a075-ec8060385a3e', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('c4af5037-21ab-5e66-b556-c7b9c4825f8d', 'c2c5f8e5-9d00-515b-a075-ec8060385a3e', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('d559edf5-bae0-597e-a824-53813f721c00', 'c2c5f8e5-9d00-515b-a075-ec8060385a3e', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “Dead in Trespasses and Sins” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
insert into public.p2p_lessons (id, module_id, title, subtitle, order_index, status, estimated_minutes, published_at, version)
