insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('f4939a8e-b9a3-5a8f-afb8-46320f14034e', '8ab26caf-d774-51fe-9234-6c1bdc2e9756', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$Sin is more than breaking a rule; it damages our relationship with the God who made us. Isaiah describes sin as separating people from God. The problem includes real guilt and real distance from God.$gs$),
  ('a3d9d829-d9e7-5b65-879b-8cca159cd398', '8ab26caf-d774-51fe-9234-6c1bdc2e9756', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$The gospel answers both sides of the problem. Through Jesus, sin is dealt with and people are brought back into peace and fellowship with God. We should therefore speak about salvation as forgiveness and restored relationship.$gs$),
  ('3171c167-a7a6-5ac6-905f-526bab87a17d', '8ab26caf-d774-51fe-9234-6c1bdc2e9756', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
