insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('b6802b37-7ccd-5858-940c-df3be0db3e2c', '8ab26caf-d774-51fe-9234-6c1bdc2e9756', 'memory_verse', $gs${"reference":"Isaiah 59:2","text":"But your iniquities have separated you from your God; and your sins have hidden His face from you.","translation":""}$gs$::jsonb, 0, true, false),
  ('10b5d664-ed9b-5542-8134-ee0b059bdcd9', '8ab26caf-d774-51fe-9234-6c1bdc2e9756', 'paragraph', $gs${"text":"Definition and simple explanation\n\nSin is more than breaking a rule; it damages our relationship with the God who made us. Isaiah describes sin as separating people from God. The problem includes real guilt and real distance from God."}$gs$::jsonb, 1, false, false),
  ('bb0fd732-acf2-5b6a-97f9-cd8ae852e230', '8ab26caf-d774-51fe-9234-6c1bdc2e9756', 'paragraph', $gs${"text":"What this means and why it matters\n\nThe gospel answers both sides of the problem. Through Jesus, sin is dealt with and people are brought back into peace and fellowship with God. We should therefore speak about salvation as forgiveness and restored relationship."}$gs$::jsonb, 2, false, false),
  ('a0481417-1fe6-5217-9f15-6417b7e4a0d6', '8ab26caf-d774-51fe-9234-6c1bdc2e9756', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('ebf69245-0005-5ee5-aced-ca9a78e61bbd', '8ab26caf-d774-51fe-9234-6c1bdc2e9756', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('9222a05b-fb9d-53e1-8c76-f32a7546d451', '8ab26caf-d774-51fe-9234-6c1bdc2e9756', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Separated from God by Sin”?"}$gs$::jsonb, 5, true, true),
  ('5287a35a-e309-5d72-8b0a-36ccf718192e', '8ab26caf-d774-51fe-9234-6c1bdc2e9756', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('578ac680-b3bb-5ada-902c-7b3cb3a50a3e', '8ab26caf-d774-51fe-9234-6c1bdc2e9756', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('d3c0fedb-bdd7-5b51-84f4-939e79c24eff', '8ab26caf-d774-51fe-9234-6c1bdc2e9756', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “Separated from God by Sin” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
