insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('8bc415e1-f011-548c-aae5-7c630f2273a3', '270606b7-1a42-5995-8d45-da2d9db31a4d', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$God’s judgment means that He responds rightly to evil. His anger is not a sudden temper or unfair hostility; it is His holy opposition to sin. Scripture says that people are accountable to Him and that rejecting the Son leaves a person under judgment.$gs$),
  ('ec5b6623-fb89-59ee-8b2d-4640b6e02d94', '270606b7-1a42-5995-8d45-da2d9db31a4d', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$This truth should make the gospel urgent, but it must never make Christians cruel or self-righteous. We share the warning with humility, remembering that salvation is offered through God’s love in Christ.$gs$),
  ('4d5f5c8a-3b9c-5d5d-ad9f-e1ae11f13b1e', '270606b7-1a42-5995-8d45-da2d9db31a4d', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
