insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('83d13731-d460-59b2-af3a-7861f7eac637', '270606b7-1a42-5995-8d45-da2d9db31a4d', 'memory_verse', $gs${"reference":"John 3:18, 36","text":"He who does not believe is condemned already… and he who does not believe the Son shall not see life, but the wrath of God abides on him.","translation":""}$gs$::jsonb, 0, true, false),
  ('20051700-0541-56f6-b315-ece2da44a5ca', '270606b7-1a42-5995-8d45-da2d9db31a4d', 'paragraph', $gs${"text":"Definition and simple explanation\n\nGod’s judgment means that He responds rightly to evil. His anger is not a sudden temper or unfair hostility; it is His holy opposition to sin. Scripture says that people are accountable to Him and that rejecting the Son leaves a person under judgment."}$gs$::jsonb, 1, false, false),
  ('46a10dc1-40c1-5000-af49-ca2bce61d985', '270606b7-1a42-5995-8d45-da2d9db31a4d', 'paragraph', $gs${"text":"What this means and why it matters\n\nThis truth should make the gospel urgent, but it must never make Christians cruel or self-righteous. We share the warning with humility, remembering that salvation is offered through God’s love in Christ."}$gs$::jsonb, 2, false, false),
  ('6bc7ad94-255b-53ba-bf61-46075285d181', '270606b7-1a42-5995-8d45-da2d9db31a4d', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('f5d3117d-fc12-550e-8886-f346edd5d292', '270606b7-1a42-5995-8d45-da2d9db31a4d', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader. God’s Pursuit of the Lost"}$gs$::jsonb, 4, false, false),
  ('a07ad995-a688-55a1-a3b7-87a8d9ca2684', '270606b7-1a42-5995-8d45-da2d9db31a4d', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Under the Wrath and Judgment of God”?"}$gs$::jsonb, 5, true, true),
  ('e98b0fe9-57e3-57e9-809e-6213f0df7702', '270606b7-1a42-5995-8d45-da2d9db31a4d', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('74d8ed6d-aa51-5a66-b0b4-6a7c4030d16e', '270606b7-1a42-5995-8d45-da2d9db31a4d', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('8f7ea7f7-595e-5093-af9b-144a73c32719', '270606b7-1a42-5995-8d45-da2d9db31a4d', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “Under the Wrath and Judgment of God” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
