insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('ceed0928-5153-5eeb-af50-4fa954693102', '79ee5446-fc19-5ec4-9afc-53c9e9e986eb', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$Common grace is God’s kindness to people generally, including those who do not yet believe. Life, food, relationships, beauty, abilities, social order, and many good gifts are examples of His kindness.$gs$),
  ('1f55c808-9cb1-5a0a-84c4-fb08cf5b9615', '79ee5446-fc19-5ec4-9afc-53c9e9e986eb', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$Common grace is not the same as saving grace. Receiving good things in this life does not by itself mean a person has been reconciled to God. God’s kindness should move us to gratitude and should encourage us to treat every person with respect.$gs$),
  ('bd357d01-f4c1-58da-bdf8-06801adb5645', '79ee5446-fc19-5ec4-9afc-53c9e9e986eb', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
