insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('074ad293-cf7b-570a-8bdc-66bd6286ec07', '79ee5446-fc19-5ec4-9afc-53c9e9e986eb', 'memory_verse', $gs${"reference":"Matthew 5:45","text":"For He makes His sun rise on the evil and on the good, and sends rain on the just and on the unjust.","translation":""}$gs$::jsonb, 0, true, false),
  ('7b80d65b-ea1f-5bc7-826b-a6bec57dbf26', '79ee5446-fc19-5ec4-9afc-53c9e9e986eb', 'paragraph', $gs${"text":"Definition and simple explanation\n\nCommon grace is God’s kindness to people generally, including those who do not yet believe. Life, food, relationships, beauty, abilities, social order, and many good gifts are examples of His kindness."}$gs$::jsonb, 1, false, false),
  ('e87f3c61-6c95-541b-bcb5-6b53c3aaefb0', '79ee5446-fc19-5ec4-9afc-53c9e9e986eb', 'paragraph', $gs${"text":"What this means and why it matters\n\nCommon grace is not the same as saving grace. Receiving good things in this life does not by itself mean a person has been reconciled to God. God’s kindness should move us to gratitude and should encourage us to treat every person with respect."}$gs$::jsonb, 2, false, false),
  ('f429e922-1cb9-52bb-a7ef-7db669b7255c', '79ee5446-fc19-5ec4-9afc-53c9e9e986eb', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('da34ec5f-2f70-5980-8bce-0e27222b3e98', '79ee5446-fc19-5ec4-9afc-53c9e9e986eb', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('da1d9927-c34d-515e-abba-18987a103b3b', '79ee5446-fc19-5ec4-9afc-53c9e9e986eb', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Common Grace: God’s Kindness to All”?"}$gs$::jsonb, 5, true, true),
  ('8649f46d-0c6f-59df-a848-44d37ad4dc52', '79ee5446-fc19-5ec4-9afc-53c9e9e986eb', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('c7a86034-ec6b-5cf3-8174-ed023167ed2f', '79ee5446-fc19-5ec4-9afc-53c9e9e986eb', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('648f4ca0-5875-5edd-a5fe-d8b43fe32789', '79ee5446-fc19-5ec4-9afc-53c9e9e986eb', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “Common Grace: God’s Kindness to All” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
insert into public.p2p_lessons (id, module_id, title, subtitle, order_index, status, estimated_minutes, published_at, version)
