insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('95b96fc2-51d0-5836-928f-b542dd8b5aac', 'ec498105-96de-575e-970e-ff6ee92f97fd', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$Creation points beyond itself to its Creator. The order, beauty, size, and wonder of the world give people reasons to recognise that God exists and that He is powerful. This is often called general revelation because it is available broadly through the created world.$gs$),
  ('af4300b5-2551-56d2-8bf8-05d48767f1af', 'ec498105-96de-575e-970e-ff6ee92f97fd', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$Creation does not explain the whole message of salvation or tell us all that we need to know about Jesus. For that, we need God’s special revelation in Scripture and the good news about Christ. The wonder of creation can prompt questions and open conversations about God.$gs$),
  ('9eed8581-d4d9-5739-a01e-1f46b2bdc509', 'ec498105-96de-575e-970e-ff6ee92f97fd', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
