insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('a317c7b0-84c2-52d0-b761-85cb3510882d', 'ec498105-96de-575e-970e-ff6ee92f97fd', 'memory_verse', $gs${"reference":"Psalm 19:1","text":"The heavens declare the glory of God; and the firmament shows His handiwork.","translation":""}$gs$::jsonb, 0, true, false),
  ('afa2082a-939b-5aeb-a454-d2bdd1fdad1f', 'ec498105-96de-575e-970e-ff6ee92f97fd', 'paragraph', $gs${"text":"Definition and simple explanation\n\nCreation points beyond itself to its Creator. The order, beauty, size, and wonder of the world give people reasons to recognise that God exists and that He is powerful. This is often called general revelation because it is available broadly through the created world."}$gs$::jsonb, 1, false, false),
  ('5eff5d86-c722-5768-8434-39e28604fdc7', 'ec498105-96de-575e-970e-ff6ee92f97fd', 'paragraph', $gs${"text":"What this means and why it matters\n\nCreation does not explain the whole message of salvation or tell us all that we need to know about Jesus. For that, we need God’s special revelation in Scripture and the good news about Christ. The wonder of creation can prompt questions and open conversations about God."}$gs$::jsonb, 2, false, false),
  ('1d2c9887-ffae-5ad2-a4c1-83eeb9c0128d', 'ec498105-96de-575e-970e-ff6ee92f97fd', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('6b3fb733-23ec-57a7-9af7-98ce83dfddfa', 'ec498105-96de-575e-970e-ff6ee92f97fd', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('bedd75bd-c59e-55b6-b601-04bef9f06c60', 'ec498105-96de-575e-970e-ff6ee92f97fd', 'reflection_question', $gs${"question":"In your own words, what is the main point of “General Revelation: Creation Testifies to God”?"}$gs$::jsonb, 5, true, true),
  ('27ec5bd1-6f96-5245-8717-11e0a8cd0de9', 'ec498105-96de-575e-970e-ff6ee92f97fd', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('20b8ff7a-fd9b-5302-b5e6-2318870d1f4e', 'ec498105-96de-575e-970e-ff6ee92f97fd', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('4b045fe8-a80e-569f-92b0-434cd2314036', 'ec498105-96de-575e-970e-ff6ee92f97fd', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “General Revelation: Creation Testifies to God” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
