insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('4a11b9b7-b824-5aa7-a17b-86e4945d9cbf', '0bb515cb-07b5-5b5d-8826-ee485b5b2e3c', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$Jesus taught that the Holy Spirit would expose the world’s wrong understanding of sin, righteousness, and judgment. The Spirit helps people see the truth about their sin and their need for Christ.$gs$),
  ('9f2ef7b2-06f2-5888-b1fc-219bee2933c6', '0bb515cb-07b5-5b5d-8826-ee485b5b2e3c', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$Conviction is not the same as mere embarrassment or feeling bad. It is an awakening to the truth that we have sinned and need God. Christians can explain the gospel, but they depend on the Spirit to work in people’s hearts.$gs$),
  ('835742a6-ad70-5dfd-a415-54d9755b4c34', '0bb515cb-07b5-5b5d-8826-ee485b5b2e3c', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
