insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('c71e9bbe-64bb-50a3-9a31-4931e4998edf', '0bb515cb-07b5-5b5d-8826-ee485b5b2e3c', 'memory_verse', $gs${"reference":"John 16:8","text":"And when He has come, He will convict the world of sin, and of righteousness, and of judgment.","translation":""}$gs$::jsonb, 0, true, false),
  ('855a986a-0594-51b5-a882-f770db6052fc', '0bb515cb-07b5-5b5d-8826-ee485b5b2e3c', 'paragraph', $gs${"text":"Definition and simple explanation\n\nJesus taught that the Holy Spirit would expose the world’s wrong understanding of sin, righteousness, and judgment. The Spirit helps people see the truth about their sin and their need for Christ."}$gs$::jsonb, 1, false, false),
  ('d31ab580-07c2-50e9-b36e-f0bfe37309ef', '0bb515cb-07b5-5b5d-8826-ee485b5b2e3c', 'paragraph', $gs${"text":"What this means and why it matters\n\nConviction is not the same as mere embarrassment or feeling bad. It is an awakening to the truth that we have sinned and need God. Christians can explain the gospel, but they depend on the Spirit to work in people’s hearts."}$gs$::jsonb, 2, false, false),
  ('dbc4e041-7ba5-50db-b65c-9cac8a302178', '0bb515cb-07b5-5b5d-8826-ee485b5b2e3c', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('210b1203-bca9-5996-ba71-62230d19f6e0', '0bb515cb-07b5-5b5d-8826-ee485b5b2e3c', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader. Why the Lost Cannot Save Themselves"}$gs$::jsonb, 4, false, false),
  ('b2434897-7329-53c3-9847-aa794a043c34', '0bb515cb-07b5-5b5d-8826-ee485b5b2e3c', 'reflection_question', $gs${"question":"In your own words, what is the main point of “The Holy Spirit’s Convicting Work”?"}$gs$::jsonb, 5, true, true),
  ('1ca21376-3af5-5093-ac35-48af9c6e8e7f', '0bb515cb-07b5-5b5d-8826-ee485b5b2e3c', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('7550efb6-f75a-5f89-9ccf-2b1bc37b55eb', '0bb515cb-07b5-5b5d-8826-ee485b5b2e3c', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('de6fd04a-1ec3-57df-866e-8d802aa3f93b', '0bb515cb-07b5-5b5d-8826-ee485b5b2e3c', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “The Holy Spirit’s Convicting Work” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
