insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('facec172-4255-55a3-98c6-1788ccbcef9a', 'f11384b5-289d-5fab-ba5a-080aa6ab6b06', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$Good actions matter, and the Bible calls believers to do what is good. But good works cannot erase past sin or purchase God’s acceptance. We cannot turn salvation into a wage that God owes us.$gs$),
  ('3dfb8414-150d-5150-92f4-7d492171518c', 'f11384b5-289d-5fab-ba5a-080aa6ab6b06', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$Ephesians 2:8–10 holds the ideas together: salvation is God’s gift received through faith, not earned by works; then those who are saved are created in Christ for good works. Good works are the result of salvation, not its price.$gs$),
  ('e1f438a9-6167-5769-865c-8e93566bce1e', 'f11384b5-289d-5fab-ba5a-080aa6ab6b06', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
