insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('ca1c9115-b49c-5f01-9c3d-be355fc4d7cd', 'f11384b5-289d-5fab-ba5a-080aa6ab6b06', 'memory_verse', $gs${"reference":"Ephesians 2:8-9","text":"For by grace you have been saved through faith, and that not of yourselves; it is the gift of God, not of works, lest anyone should boast.","translation":""}$gs$::jsonb, 0, true, false),
  ('036dda93-813e-57ce-91cd-b5c3e42b8952', 'f11384b5-289d-5fab-ba5a-080aa6ab6b06', 'paragraph', $gs${"text":"Definition and simple explanation\n\nGood actions matter, and the Bible calls believers to do what is good. But good works cannot erase past sin or purchase God’s acceptance. We cannot turn salvation into a wage that God owes us."}$gs$::jsonb, 1, false, false),
  ('7492ffba-379e-56aa-b8c4-210eff930ca8', 'f11384b5-289d-5fab-ba5a-080aa6ab6b06', 'paragraph', $gs${"text":"What this means and why it matters\n\nEphesians 2:8–10 holds the ideas together: salvation is God’s gift received through faith, not earned by works; then those who are saved are created in Christ for good works. Good works are the result of salvation, not its price."}$gs$::jsonb, 2, false, false),
  ('5b2c8c14-2645-59b5-b21a-9fbfb7d36898', 'f11384b5-289d-5fab-ba5a-080aa6ab6b06', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('149dc747-bce3-5187-8123-3ced5cdfee2b', 'f11384b5-289d-5fab-ba5a-080aa6ab6b06', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('64eb2f9b-da36-52e2-ad4b-e681a1f6d83b', 'f11384b5-289d-5fab-ba5a-080aa6ab6b06', 'reflection_question', $gs${"question":"In your own words, what is the main point of “The Insufficiency of Good Works”?"}$gs$::jsonb, 5, true, true),
  ('3fbe046b-5887-5cc3-b5f1-fdf8f15cb0c6', 'f11384b5-289d-5fab-ba5a-080aa6ab6b06', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
