insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('d0fd1672-35ba-5b5c-8df4-7c33be1a91a1', 'e7942d9b-a207-536f-b703-1f1ec1e63209', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$Sin is not only a list of wrong actions; it can become a power that enslaves our desires and choices. Jesus said that the one who practises sin is a slave to sin. People may make real choices, but sin distorts what they love and how they use their freedom.$gs$),
  ('547b32ef-9ee7-5227-8aa1-e4944f6b5354', 'e7942d9b-a207-536f-b703-1f1ec1e63209', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$Jesus offers freedom from sin’s mastery. This does not mean believers never struggle again. It means Christ begins a new life in which sin is no longer their rightful master, and they learn to live in obedience through His help.$gs$),
  ('a42003c2-464a-559d-ae8d-7c1b66d1b3d9', 'e7942d9b-a207-536f-b703-1f1ec1e63209', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
insert into public.p2p_reflection_questions (id, lesson_id, question, display_order) values
  ('77dbf80d-56fd-5c48-adca-54f019598fcb', 'e7942d9b-a207-536f-b703-1f1ec1e63209', $gs$In your own words, what is the main point of “The Bondage of the Will to Sin”?$gs$, 1),
  ('7f57a28e-f69b-59fd-bc3c-5f7bb8eb32cc', 'e7942d9b-a207-536f-b703-1f1ec1e63209', $gs$What part of this teaching is easiest for you to understand, and what part would you like to discuss further?$gs$, 2),
  ('c3d30b43-524a-5d6c-94a9-1103cb2486c8', 'e7942d9b-a207-536f-b703-1f1ec1e63209', $gs$How could this truth shape one attitude or action in your life this week?$gs$, 3)
insert into public.p2p_assignments (id, lesson_id, title, instructions)
insert into public.p2p_assignment_questions (id, assignment_id, question, display_order) values
  ('656c890e-2387-5965-bf94-be6f548c5466', '69f1cf4a-0c10-5788-befd-60412cba59bd', $gs$Define the main idea in the lesson “The Bondage of the Will to Sin” using simple language.$gs$, 1),
  ('29d58bb9-45ee-536f-ae11-af2aa656b50a', '69f1cf4a-0c10-5788-befd-60412cba59bd', $gs$What does the key Bible passage teach about God, people, or the Christian life?$gs$, 2),
  ('dfea28a5-6d98-561f-8bc0-94471d4b7b89', '69f1cf4a-0c10-5788-befd-60412cba59bd', $gs$Explain why this teaching matters. Give one reason from the lesson.$gs$, 3),
  ('067b62a1-fc0e-5a26-8ff6-0c64b48108ad', '69f1cf4a-0c10-5788-befd-60412cba59bd', $gs$Give one practical example of how someone could respond to this teaching.$gs$, 4)
insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('a2c3fb89-aaca-50dd-a90f-4119aefade5c', 'e7942d9b-a207-536f-b703-1f1ec1e63209', 'memory_verse', $gs${"reference":"John 8:34","text":"Most assuredly, I say to you, whoever commits sin is a slave of sin.","translation":""}$gs$::jsonb, 0, true, false),
  ('ec1a7ee1-08c3-5b57-a396-debbeea25d91', 'e7942d9b-a207-536f-b703-1f1ec1e63209', 'paragraph', $gs${"text":"Definition and simple explanation\n\nSin is not only a list of wrong actions; it can become a power that enslaves our desires and choices. Jesus said that the one who practises sin is a slave to sin. People may make real choices, but sin distorts what they love and how they use their freedom."}$gs$::jsonb, 1, false, false),
  ('96b29e19-5c4a-5e0e-ba99-a8e4aa746d02', 'e7942d9b-a207-536f-b703-1f1ec1e63209', 'paragraph', $gs${"text":"What this means and why it matters\n\nJesus offers freedom from sin’s mastery. This does not mean believers never struggle again. It means Christ begins a new life in which sin is no longer their rightful master, and they learn to live in obedience through His help."}$gs$::jsonb, 2, false, false),
  ('3ec73f9f-78e8-5d46-a9b9-c5c6f5748aa7', 'e7942d9b-a207-536f-b703-1f1ec1e63209', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('dda5b72c-80c2-5c04-9e2b-0ef52c1fa0ec', 'e7942d9b-a207-536f-b703-1f1ec1e63209', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('8574b41d-465f-54ea-915d-c9bf93acd5bc', 'e7942d9b-a207-536f-b703-1f1ec1e63209', 'reflection_question', $gs${"question":"In your own words, what is the main point of “The Bondage of the Will to Sin”?"}$gs$::jsonb, 5, true, true),
  ('b18a5cc4-4f86-5b7d-95fc-efe20fbb3895', 'e7942d9b-a207-536f-b703-1f1ec1e63209', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('953d199e-a101-5bdf-b9c2-fe3f9f4d1698', 'e7942d9b-a207-536f-b703-1f1ec1e63209', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('27124057-7a8e-5155-a84c-22eb6cf39c19', 'e7942d9b-a207-536f-b703-1f1ec1e63209', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “The Bondage of the Will to Sin” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
insert into public.p2p_lessons (id, module_id, title, subtitle, order_index, status, estimated_minutes, published_at, version)
