insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('f38092b8-c804-5115-bfc3-961ae67fbd56', '1a59347c-a73c-5050-ac93-6a902560464c', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$A person can know religious language, attend services, and perform outward practices while their heart remains unchanged. Jesus warned about honouring God with words while keeping the heart far from Him.$gs$),
  ('add3a2f7-6bbb-580c-b310-ffa88ede85b9', '1a59347c-a73c-5050-ac93-6a902560464c', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$Regeneration means being given new spiritual life by God. Outward religion cannot replace this inward work. Religious practices are valuable when they express genuine trust and love for God, but they cannot be used as a mask or as a way to earn salvation.$gs$),
  ('4bf56361-aee6-5c3c-9973-3da406281fbf', '1a59347c-a73c-5050-ac93-6a902560464c', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
