insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('e6b688b0-8c3e-5527-9a05-93522828a54d', '1a59347c-a73c-5050-ac93-6a902560464c', 'memory_verse', $gs${"reference":"Matthew 15:8","text":"This people honors Me with their lips, but their heart is far from Me.","translation":""}$gs$::jsonb, 0, true, false),
  ('4c0be7f7-76d4-5701-9a91-d60c1bdac437', '1a59347c-a73c-5050-ac93-6a902560464c', 'paragraph', $gs${"text":"Definition and simple explanation\n\nA person can know religious language, attend services, and perform outward practices while their heart remains unchanged. Jesus warned about honouring God with words while keeping the heart far from Him."}$gs$::jsonb, 1, false, false),
  ('ad7be287-984a-5488-b06b-ce058ee4fc22', '1a59347c-a73c-5050-ac93-6a902560464c', 'paragraph', $gs${"text":"What this means and why it matters\n\nRegeneration means being given new spiritual life by God. Outward religion cannot replace this inward work. Religious practices are valuable when they express genuine trust and love for God, but they cannot be used as a mask or as a way to earn salvation."}$gs$::jsonb, 2, false, false),
  ('4b256243-e570-52de-89c5-b2b01a5d66ea', '1a59347c-a73c-5050-ac93-6a902560464c', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('b98f9e9e-b264-5dbb-8a60-59c306e5260c', '1a59347c-a73c-5050-ac93-6a902560464c', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader. Living With Compassion for the Lost"}$gs$::jsonb, 4, false, false),
  ('b9747fef-c6c3-5899-b81e-54f453cc70bd', '1a59347c-a73c-5050-ac93-6a902560464c', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Religion Without Regeneration”?"}$gs$::jsonb, 5, true, true),
  ('a9faf6e7-ccaf-56f4-809d-4ee2dad2d215', '1a59347c-a73c-5050-ac93-6a902560464c', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('68246e47-177f-5069-bf3f-fe082e108daf', '1a59347c-a73c-5050-ac93-6a902560464c', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('1d81cd35-6776-50fd-afbc-b8311827bdcd', '1a59347c-a73c-5050-ac93-6a902560464c', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “Religion Without Regeneration” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
