insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('45981a8b-c0ba-59c3-8cbe-f9604fcbad27', 'b2db92c9-f617-566a-8888-714734b61ee4', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$Jesus looked at people with compassion. He saw more than their outward behaviour or social position; He saw people who were weary, vulnerable, and in need of God’s care. Christians are called to see people as persons made in God’s image and worthy of dignity.$gs$),
  ('5d36e44c-ab22-52ed-82f3-abef4067f94d', 'b2db92c9-f617-566a-8888-714734b61ee4', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$Compassion is not approving every action or ignoring truth. It means speaking truth with patience, listening carefully, serving where possible, and desiring another person’s good. Gospel concern should lead to loving action rather than criticism.$gs$),
  ('e6c0c03c-4533-5112-a798-59e3b0f928ce', 'b2db92c9-f617-566a-8888-714734b61ee4', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
