insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('516f69d6-60fa-56d2-bf3c-3cf5c67623f7', 'b2db92c9-f617-566a-8888-714734b61ee4', 'memory_verse', $gs${"reference":"Matthew 9:36","text":"But when He saw the multitudes, He was moved with compassion for them, because they were weary and scattered, like sheep having no shepherd.","translation":""}$gs$::jsonb, 0, true, false),
  ('69632efb-dfab-5547-bc6e-9c070f2c6c5e', 'b2db92c9-f617-566a-8888-714734b61ee4', 'paragraph', $gs${"text":"Definition and simple explanation\n\nJesus looked at people with compassion. He saw more than their outward behaviour or social position; He saw people who were weary, vulnerable, and in need of God’s care. Christians are called to see people as persons made in God’s image and worthy of dignity."}$gs$::jsonb, 1, false, false),
  ('3bf6d432-1454-5c6a-acc2-9c6bd2df154f', 'b2db92c9-f617-566a-8888-714734b61ee4', 'paragraph', $gs${"text":"What this means and why it matters\n\nCompassion is not approving every action or ignoring truth. It means speaking truth with patience, listening carefully, serving where possible, and desiring another person’s good. Gospel concern should lead to loving action rather than criticism."}$gs$::jsonb, 2, false, false),
  ('900db106-5a51-54d1-b08e-b950082d1175', 'b2db92c9-f617-566a-8888-714734b61ee4', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('45207b70-40c8-520c-bd18-183beff3d854', 'b2db92c9-f617-566a-8888-714734b61ee4', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('2b84e6ca-f942-5cc4-a131-0586b32bd185', 'b2db92c9-f617-566a-8888-714734b61ee4', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Seeing People as God Sees Them”?"}$gs$::jsonb, 5, true, true),
  ('f857e075-62ac-5a30-95bf-9a2cf2ec2475', 'b2db92c9-f617-566a-8888-714734b61ee4', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('82101bda-c603-535b-a6a9-233f2449d030', 'b2db92c9-f617-566a-8888-714734b61ee4', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('7805dbd1-06cc-55de-b149-a147a1efe02d', 'b2db92c9-f617-566a-8888-714734b61ee4', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “Seeing People as God Sees Them” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
