insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('fcba758b-5450-5031-a2fc-9439eb7af4da', '5db4bc9a-62a0-5bb2-b28b-852fcf0011d2', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$Prayer for people who do not yet know Christ expresses love and dependence on God. Paul prayed earnestly for others to be saved. We can ask God to open hearts, bring understanding, provide opportunities, and give us wisdom and courage.$gs$),
  ('97bd21d0-f20c-59c8-b17a-6068cbd6c970', '5db4bc9a-62a0-5bb2-b28b-852fcf0011d2', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$Prayer does not replace personal witness; it supports it. Pray specifically and respectfully, without treating people as projects. Continue to show friendship and kindness whether or not someone responds quickly.$gs$),
  ('bfecda4f-ac37-5618-a63e-477e06c94fcf', '5db4bc9a-62a0-5bb2-b28b-852fcf0011d2', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
