insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('07c12c3a-434b-52b8-b6ea-cfdf6bc88c6a', '5db4bc9a-62a0-5bb2-b28b-852fcf0011d2', 'memory_verse', $gs${"reference":"Romans 10:1","text":"Brethren, my heart’s desire and prayer to God for Israel is that they may be saved.","translation":""}$gs$::jsonb, 0, true, false),
  ('8077a013-44c7-5901-8802-dd54ea750759', '5db4bc9a-62a0-5bb2-b28b-852fcf0011d2', 'paragraph', $gs${"text":"Definition and simple explanation\n\nPrayer for people who do not yet know Christ expresses love and dependence on God. Paul prayed earnestly for others to be saved. We can ask God to open hearts, bring understanding, provide opportunities, and give us wisdom and courage."}$gs$::jsonb, 1, false, false),
  ('876d5f65-ddd5-59b9-bc8c-a2cad2fa958b', '5db4bc9a-62a0-5bb2-b28b-852fcf0011d2', 'paragraph', $gs${"text":"What this means and why it matters\n\nPrayer does not replace personal witness; it supports it. Pray specifically and respectfully, without treating people as projects. Continue to show friendship and kindness whether or not someone responds quickly."}$gs$::jsonb, 2, false, false),
  ('769820ba-7e63-53c6-9e27-67b8e50ea7da', '5db4bc9a-62a0-5bb2-b28b-852fcf0011d2', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('b4d1ad02-51ba-5a21-b52e-af6f68dbb4da', '5db4bc9a-62a0-5bb2-b28b-852fcf0011d2', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('be7bbfe5-991a-52dc-9691-c5dd4f192ece', '5db4bc9a-62a0-5bb2-b28b-852fcf0011d2', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Praying for the Unsaved in Your Life”?"}$gs$::jsonb, 5, true, true),
  ('0df55a58-27e4-5dfb-a61b-c6e2be3dcb6a', '5db4bc9a-62a0-5bb2-b28b-852fcf0011d2', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('5215b3e7-cbd2-55b3-aa45-0f4a4d2a2b28', '5db4bc9a-62a0-5bb2-b28b-852fcf0011d2', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('88bf22ff-5304-53be-8666-b339d562bcea', '5db4bc9a-62a0-5bb2-b28b-852fcf0011d2', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “Praying for the Unsaved in Your Life” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
