insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('ee538aba-0541-56df-bc99-841dda6cbaf2', '45802359-ee8b-5b2b-bf59-8a0ee3d30e73', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$Jesus looked at people with compassion. He saw more than their outward behaviour or social position; He saw people who were weary, vulnerable, and in need of God’s care. Christians are called to see people as persons made in God’s image and worthy of dignity.$gs$),
  ('51b1df7c-e7d1-54e4-a587-9a9c7c36b5c0', '45802359-ee8b-5b2b-bf59-8a0ee3d30e73', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$Compassion is not approving every action or ignoring truth. It means speaking truth with patience, listening carefully, serving where possible, and desiring another person’s good. Gospel concern should lead to loving action rather than criticism.$gs$),
  ('3254f5e2-548d-5bbe-b054-6de75c60febe', '45802359-ee8b-5b2b-bf59-8a0ee3d30e73', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
