  ('9c32cd5c-1fcb-5dcd-8238-f7e552623192', '45802359-ee8b-5b2b-bf59-8a0ee3d30e73', 'paragraph', $gs${"text":"What this means and why it matters\n\nCompassion is not approving every action or ignoring truth. It means speaking truth with patience, listening carefully, serving where possible, and desiring another person’s good. Gospel concern should lead to loving action rather than criticism."}$gs$::jsonb, 2, false, false),
  ('905191e4-5af1-529e-a531-f49bde9efba1', '45802359-ee8b-5b2b-bf59-8a0ee3d30e73', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
