  ('ac12e78f-5864-5266-9f23-670dfb0c3733', '45802359-ee8b-5b2b-bf59-8a0ee3d30e73', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('47cffc1c-8c27-53d5-9b51-956e9ea41581', '45802359-ee8b-5b2b-bf59-8a0ee3d30e73', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('95fe5dfd-595e-56f3-9f54-4075d4cedd3b', '45802359-ee8b-5b2b-bf59-8a0ee3d30e73', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “A Lifetime of Gospel-Centered Compassion” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
