insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('717a93b7-91f1-56b6-8590-99a60b54af79', '01980f6e-8cb0-5595-a343-5103d301ffb1', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$The Bible teaches that Jesus is truly God and truly human. He did not stop being God when He became human; the eternal Son took on a real human nature. He experienced human life, including hunger, tiredness, sorrow, and suffering.$gs$),
  ('29613534-dd5a-5ae7-b2f6-9b5b42557848', '01980f6e-8cb0-5595-a343-5103d301ffb1', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$Because Jesus is God, He reveals God and has power to save. Because He is truly human, He can represent us and sympathise with our weakness. Christians should avoid imagining Jesus as partly God or merely a good human teacher.$gs$),
  ('f69d2724-b80a-597a-baeb-c25ab70c36de', '01980f6e-8cb0-5595-a343-5103d301ffb1', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
