insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('e97caed9-2e0b-52b3-89a4-45b64a92f346', '01980f6e-8cb0-5595-a343-5103d301ffb1', 'memory_verse', $gs${"reference":"John 1:14","text":"And the Word became flesh and dwelt among us.","translation":""}$gs$::jsonb, 0, true, false),
  ('201d2cc1-923b-5bf1-a3ca-309c89797973', '01980f6e-8cb0-5595-a343-5103d301ffb1', 'paragraph', $gs${"text":"Definition and simple explanation\n\nThe Bible teaches that Jesus is truly God and truly human. He did not stop being God when He became human; the eternal Son took on a real human nature. He experienced human life, including hunger, tiredness, sorrow, and suffering."}$gs$::jsonb, 1, false, false),
  ('7c72bd4b-51f2-580a-af96-0798fdf76910', '01980f6e-8cb0-5595-a343-5103d301ffb1', 'paragraph', $gs${"text":"What this means and why it matters\n\nBecause Jesus is God, He reveals God and has power to save. Because He is truly human, He can represent us and sympathise with our weakness. Christians should avoid imagining Jesus as partly God or merely a good human teacher."}$gs$::jsonb, 2, false, false),
  ('ce69aa7d-5fab-5ac8-b552-ecd91759bc46', '01980f6e-8cb0-5595-a343-5103d301ffb1', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('46f36208-20ff-53e6-b831-686c80ed390b', '01980f6e-8cb0-5595-a343-5103d301ffb1', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('df3444ca-a199-5ee3-a5d0-05734e349d20', '01980f6e-8cb0-5595-a343-5103d301ffb1', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Fully God, Fully Man”?"}$gs$::jsonb, 5, true, true),
  ('83cfdb5c-7890-5428-8ed8-a7cadfb662d2', '01980f6e-8cb0-5595-a343-5103d301ffb1', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('58916e71-c224-5054-9bc0-1dc9ac50853c', '01980f6e-8cb0-5595-a343-5103d301ffb1', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('09c6e9cb-3310-5d0f-ae9d-03e11a49ae0f', '01980f6e-8cb0-5595-a343-5103d301ffb1', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “Fully God, Fully Man” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
