insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('004321a8-0b34-552c-a1da-ce558a87def8', '30e612e3-1277-56a2-b8c2-14355aea956b', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$Jesus experienced real temptation and pressure, yet He never sinned. His obedience was complete. He understands human weakness because He truly lived as a human being, but He did not share our guilt or give in to sin.$gs$),
  ('486b5889-4bee-5437-812c-73437df2a901', '30e612e3-1277-56a2-b8c2-14355aea956b', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$His sinlessness matters because He could offer Himself as the spotless sacrifice for sinners. It also means He is a trustworthy example. We can approach Him for mercy and help when we are tempted.$gs$),
  ('504053d7-0a37-5b6e-a24a-cfc814fd2aa3', '30e612e3-1277-56a2-b8c2-14355aea956b', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
insert into public.p2p_reflection_questions (id, lesson_id, question, display_order) values
  ('06922e19-a5f0-5e5b-b9fb-fcf2303a27e8', '30e612e3-1277-56a2-b8c2-14355aea956b', $gs$In your own words, what is the main point of “Christ’s Sinless Life”?$gs$, 1),
  ('2cc8b6a1-fc5d-54a4-85a3-7037cb5dd80a', '30e612e3-1277-56a2-b8c2-14355aea956b', $gs$What part of this teaching is easiest for you to understand, and what part would you like to discuss further?$gs$, 2),
  ('fc69bb38-8cdb-5601-acc0-ab223c40d702', '30e612e3-1277-56a2-b8c2-14355aea956b', $gs$How could this truth shape one attitude or action in your life this week?$gs$, 3)
