insert into public.p2p_assignment_questions (id, assignment_id, question, display_order) values
  ('1bc3ad3e-5f4b-5b82-abbf-87f8a7e5174b', '275b76c5-3187-5fe2-8f16-7dc43811ae52', $gs$Define the main idea in the lesson “Christ’s Sinless Life” using simple language.$gs$, 1),
  ('40cca821-2926-55d1-b79f-2cbc9775b75d', '275b76c5-3187-5fe2-8f16-7dc43811ae52', $gs$What does the key Bible passage teach about God, people, or the Christian life?$gs$, 2),
  ('5ba967a9-7976-52c0-b7b1-82dee1b9c9c4', '275b76c5-3187-5fe2-8f16-7dc43811ae52', $gs$Explain why this teaching matters. Give one reason from the lesson.$gs$, 3),
  ('7340b9a2-926f-59cf-a04f-58ff43171432', '275b76c5-3187-5fe2-8f16-7dc43811ae52', $gs$Give one practical example of how someone could respond to this teaching.$gs$, 4)
insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('35e4c74e-bf33-5944-b933-4f8f7c41bde5', '30e612e3-1277-56a2-b8c2-14355aea956b', 'memory_verse', $gs${"reference":"Hebrews 4:15","text":"For we do not have a High Priest who cannot sympathize with our weaknesses, but was in all points tempted as we are, yet without sin.","translation":""}$gs$::jsonb, 0, true, false),
  ('57472947-d5cc-5301-8694-e172ff2417a4', '30e612e3-1277-56a2-b8c2-14355aea956b', 'paragraph', $gs${"text":"Definition and simple explanation\n\nJesus experienced real temptation and pressure, yet He never sinned. His obedience was complete. He understands human weakness because He truly lived as a human being, but He did not share our guilt or give in to sin."}$gs$::jsonb, 1, false, false),
  ('e4358263-bdf6-52f9-bab3-e718becac468', '30e612e3-1277-56a2-b8c2-14355aea956b', 'paragraph', $gs${"text":"What this means and why it matters\n\nHis sinlessness matters because He could offer Himself as the spotless sacrifice for sinners. It also means He is a trustworthy example. We can approach Him for mercy and help when we are tempted."}$gs$::jsonb, 2, false, false),
  ('542509f9-5f44-563d-852f-5a735f9ee92d', '30e612e3-1277-56a2-b8c2-14355aea956b', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('3dd906cd-02ab-567f-a2f9-2783f488cd52', '30e612e3-1277-56a2-b8c2-14355aea956b', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader. The Work of Christ"}$gs$::jsonb, 4, false, false),
  ('e437a797-8f18-50e1-90b9-81fe7605baac', '30e612e3-1277-56a2-b8c2-14355aea956b', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Christ’s Sinless Life”?"}$gs$::jsonb, 5, true, true),
  ('e8f59079-57b7-5d88-863a-2a72174ce57d', '30e612e3-1277-56a2-b8c2-14355aea956b', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('c2abf98e-62e8-5b9c-94ea-fc655ce02a87', '30e612e3-1277-56a2-b8c2-14355aea956b', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('f4a8c55b-7ad9-5bef-8510-baa9efea7eb2', '30e612e3-1277-56a2-b8c2-14355aea956b', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “Christ’s Sinless Life” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
