insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('ebfa4e33-1431-5bc2-8906-6ad1d7e1906b', '80782e96-0ba7-5876-b29a-af325c90f779', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$Jesus’ death was for us. He took the judgment our sins deserved and gave Himself willingly. This is called substitution: Jesus stood in the place of sinners. His death was not an accident or merely an example of courage; it was central to God’s saving plan.$gs$),
  ('38908aea-b937-5450-97b8-b1fbce82f42b', '80782e96-0ba7-5876-b29a-af325c90f779', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$The cross shows both how serious sin is and how great God’s love is. We do not earn this gift. We receive it by faith, trusting what Jesus has done rather than relying on our own goodness.$gs$),
  ('ee426746-a195-5da6-a0d6-a000351abd5e', '80782e96-0ba7-5876-b29a-af325c90f779', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
insert into public.p2p_reflection_questions (id, lesson_id, question, display_order) values
  ('3901331d-7e12-503f-adf0-c8ad3c9f7b48', '80782e96-0ba7-5876-b29a-af325c90f779', $gs$In your own words, what is the main point of “His Substitutionary Death”?$gs$, 1),
  ('cef2c0cb-f145-5262-8609-309ed2bfdb1e', '80782e96-0ba7-5876-b29a-af325c90f779', $gs$What part of this teaching is easiest for you to understand, and what part would you like to discuss further?$gs$, 2),
  ('bc251630-dffb-5584-86e7-186f03a125f6', '80782e96-0ba7-5876-b29a-af325c90f779', $gs$How could this truth shape one attitude or action in your life this week?$gs$, 3)
