insert into public.p2p_assignment_questions (id, assignment_id, question, display_order) values
  ('771169c2-629e-5cc5-822d-f557b88ca1ef', '881b21e4-0e1e-5062-8318-53b8fc70cb36', $gs$Define the main idea in the lesson “His Substitutionary Death” using simple language.$gs$, 1),
  ('818f1e38-c343-569b-a7e4-aa70636a4f4e', '881b21e4-0e1e-5062-8318-53b8fc70cb36', $gs$What does the key Bible passage teach about God, people, or the Christian life?$gs$, 2),
  ('090fb5d5-9c06-5f35-abdb-3b08cc9bcfbe', '881b21e4-0e1e-5062-8318-53b8fc70cb36', $gs$Explain why this teaching matters. Give one reason from the lesson.$gs$, 3),
  ('ad10936c-84f0-5d8f-b9ec-a94c4dd5b5f5', '881b21e4-0e1e-5062-8318-53b8fc70cb36', $gs$Give one practical example of how someone could respond to this teaching.$gs$, 4)
insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('b2475d51-8089-5138-bb95-e6645fb45d32', '80782e96-0ba7-5876-b29a-af325c90f779', 'memory_verse', $gs${"reference":"1 Peter 2:24","text":"He Himself bore our sins in His own body on the tree.","translation":""}$gs$::jsonb, 0, true, false),
  ('c060eb29-40fc-5a10-ba33-89579d219ab1', '80782e96-0ba7-5876-b29a-af325c90f779', 'paragraph', $gs${"text":"Definition and simple explanation\n\nJesus’ death was for us. He took the judgment our sins deserved and gave Himself willingly. This is called substitution: Jesus stood in the place of sinners. His death was not an accident or merely an example of courage; it was central to God’s saving plan."}$gs$::jsonb, 1, false, false),
  ('db797de0-e8cc-5618-a2e4-44462d347e7e', '80782e96-0ba7-5876-b29a-af325c90f779', 'paragraph', $gs${"text":"What this means and why it matters\n\nThe cross shows both how serious sin is and how great God’s love is. We do not earn this gift. We receive it by faith, trusting what Jesus has done rather than relying on our own goodness."}$gs$::jsonb, 2, false, false),
  ('c76084f5-c22d-55e6-afbe-dae0a09c5f69', '80782e96-0ba7-5876-b29a-af325c90f779', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('406d2a1e-20fa-5b20-9924-7014e20a9967', '80782e96-0ba7-5876-b29a-af325c90f779', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('c671bc46-9613-5d33-93ae-a84b4ad67cda', '80782e96-0ba7-5876-b29a-af325c90f779', 'reflection_question', $gs${"question":"In your own words, what is the main point of “His Substitutionary Death”?"}$gs$::jsonb, 5, true, true),
  ('f5320fd3-2452-51a3-9652-2a0486d69d65', '80782e96-0ba7-5876-b29a-af325c90f779', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('2176ab21-f3b4-5afc-97a0-72f7fb951650', '80782e96-0ba7-5876-b29a-af325c90f779', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('ec09dd8e-4ea5-51d7-9f40-6838cbe77128', '80782e96-0ba7-5876-b29a-af325c90f779', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “His Substitutionary Death” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
