insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('f3e95ed3-bdef-5ae9-b888-1191fcb9028d', 'ab7f90f7-bff8-54d2-9c04-c7114e4b658d', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$The resurrection means that Jesus physically rose from the dead. The Christian faith is not based only on the memory of a wise teacher or on the idea that His influence continued. The apostles proclaimed that the risen Jesus was seen by witnesses.$gs$),
  ('e2434dc9-50d5-560f-8373-4be111029be3', 'ab7f90f7-bff8-54d2-9c04-c7114e4b658d', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$The resurrection shows that death did not defeat Jesus and that His saving work is accepted. It gives believers hope that death is not the end and that those who belong to Christ will also be raised.$gs$),
  ('9b865b41-976e-53d5-8a9e-c5e85d8803a2', 'ab7f90f7-bff8-54d2-9c04-c7114e4b658d', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
