insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('faff7f77-5f5f-5409-b81e-1153b5d0bcce', 'ab7f90f7-bff8-54d2-9c04-c7114e4b658d', 'memory_verse', $gs${"reference":"1 Corinthians 15:20","text":"But now Christ is risen from the dead, and has become the firstfruits of those who have fallen asleep.","translation":""}$gs$::jsonb, 0, true, false),
  ('4804052b-e25e-5c10-8d09-2d3ded9104da', 'ab7f90f7-bff8-54d2-9c04-c7114e4b658d', 'paragraph', $gs${"text":"Definition and simple explanation\n\nThe resurrection means that Jesus physically rose from the dead. The Christian faith is not based only on the memory of a wise teacher or on the idea that His influence continued. The apostles proclaimed that the risen Jesus was seen by witnesses."}$gs$::jsonb, 1, false, false),
  ('b6763457-4a93-5073-8471-811cc3866b1b', 'ab7f90f7-bff8-54d2-9c04-c7114e4b658d', 'paragraph', $gs${"text":"What this means and why it matters\n\nThe resurrection shows that death did not defeat Jesus and that His saving work is accepted. It gives believers hope that death is not the end and that those who belong to Christ will also be raised."}$gs$::jsonb, 2, false, false),
  ('5d139957-fc2c-59ba-ae3d-2b975c2e48ec', 'ab7f90f7-bff8-54d2-9c04-c7114e4b658d', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('b4a542ef-c280-5ba0-8ebc-c193f47b5842', 'ab7f90f7-bff8-54d2-9c04-c7114e4b658d', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('9b276d92-df67-5ee1-8905-d975ec623e22', 'ab7f90f7-bff8-54d2-9c04-c7114e4b658d', 'reflection_question', $gs${"question":"In your own words, what is the main point of “His Bodily Resurrection”?"}$gs$::jsonb, 5, true, true),
  ('f8c2b1a9-8951-5ce2-983a-23ee9f588c11', 'ab7f90f7-bff8-54d2-9c04-c7114e4b658d', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('1ac2a7ef-0d3e-54c7-97cb-6e167acc9cd4', 'ab7f90f7-bff8-54d2-9c04-c7114e4b658d', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('a656b273-d4db-5c7f-b510-4ab2d39192c5', 'ab7f90f7-bff8-54d2-9c04-c7114e4b658d', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “His Bodily Resurrection” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
