insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('b08b80a1-1d72-5179-bcc7-9cf1f4e5f377', '2630eddb-e2ea-5107-b631-1d9852e639ad', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$After His resurrection, Jesus was taken up into heaven. The ascension does not mean He is absent or inactive. Scripture presents Him as reigning at God’s right hand, with authority and continuing care for His people.$gs$),
  ('3da5d196-a39f-54ce-8b9c-7a146aafe717', '2630eddb-e2ea-5107-b631-1d9852e639ad', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$Because Jesus reigns, Christians can pray with confidence, endure hardship with hope, and live under His authority. His reign also reminds us that history is moving toward God’s purpose.$gs$),
  ('43722547-30bd-5144-8588-5c8448707829', '2630eddb-e2ea-5107-b631-1d9852e639ad', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
