insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('b8af1b99-ce3e-5e9e-a999-c3df5bb7a057', '2630eddb-e2ea-5107-b631-1d9852e639ad', 'memory_verse', $gs${"reference":"Mark 16:19","text":"So then, after the Lord had spoken to them, He was received up into heaven, and sat down at the right hand of God.","translation":""}$gs$::jsonb, 0, true, false),
  ('66035089-8628-5a9a-a5d9-b2c1f3145ff2', '2630eddb-e2ea-5107-b631-1d9852e639ad', 'paragraph', $gs${"text":"Definition and simple explanation\n\nAfter His resurrection, Jesus was taken up into heaven. The ascension does not mean He is absent or inactive. Scripture presents Him as reigning at God’s right hand, with authority and continuing care for His people."}$gs$::jsonb, 1, false, false),
  ('2606ac7a-6a30-5bfd-9726-10a99bd2616c', '2630eddb-e2ea-5107-b631-1d9852e639ad', 'paragraph', $gs${"text":"What this means and why it matters\n\nBecause Jesus reigns, Christians can pray with confidence, endure hardship with hope, and live under His authority. His reign also reminds us that history is moving toward God’s purpose."}$gs$::jsonb, 2, false, false),
  ('e893f952-db71-50bd-9ecf-d9c56dfb221a', '2630eddb-e2ea-5107-b631-1d9852e639ad', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('d7270a6e-a7a2-5409-9835-ad8827cd371d', '2630eddb-e2ea-5107-b631-1d9852e639ad', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader. The Titles and Roles of Christ"}$gs$::jsonb, 4, false, false),
  ('94f493fe-71db-555d-9c8e-a8075721d109', '2630eddb-e2ea-5107-b631-1d9852e639ad', 'reflection_question', $gs${"question":"In your own words, what is the main point of “His Ascension and Present Reign”?"}$gs$::jsonb, 5, true, true),
  ('f81a4468-8cca-5c85-801e-27adde8c9e65', '2630eddb-e2ea-5107-b631-1d9852e639ad', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('2724f6fc-cc79-5dd2-9156-03430aff6581', '2630eddb-e2ea-5107-b631-1d9852e639ad', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('58c28d16-820f-5c61-9610-861712c36fca', '2630eddb-e2ea-5107-b631-1d9852e639ad', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “His Ascension and Present Reign” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
