insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('df2828f7-d8ff-546f-a79a-fcc13b49a44d', 'f6cc095a-1c77-562b-8b83-8f0de9104fa3', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$A saviour rescues someone from danger. Jesus is called Saviour because He rescues people from sin and its consequences. He does more than offer advice or a better example: He gives Himself to accomplish the rescue we cannot accomplish for ourselves.$gs$),
  ('a0b7f62c-1166-55c0-bf2d-f6abdf4fe70b', 'f6cc095a-1c77-562b-8b83-8f0de9104fa3', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$To call Jesus Saviour is to admit that we need rescue and to trust Him. This should produce gratitude, humility, and a desire to share the good news with others.$gs$),
  ('10b18413-154b-5ec1-9fbc-50ae66e16d39', 'f6cc095a-1c77-562b-8b83-8f0de9104fa3', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
