insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('e52d6a9e-a9a6-53bc-b441-0f617b61266e', 'f6cc095a-1c77-562b-8b83-8f0de9104fa3', 'memory_verse', $gs${"reference":"Luke 2:11","text":"For unto you is born this day in the city of David a Savior, who is Christ the Lord.","translation":""}$gs$::jsonb, 0, true, false),
  ('051bbd1d-c935-5ebd-89ac-e8c9034e1599', 'f6cc095a-1c77-562b-8b83-8f0de9104fa3', 'paragraph', $gs${"text":"Definition and simple explanation\n\nA saviour rescues someone from danger. Jesus is called Saviour because He rescues people from sin and its consequences. He does more than offer advice or a better example: He gives Himself to accomplish the rescue we cannot accomplish for ourselves."}$gs$::jsonb, 1, false, false),
  ('04284ec3-ece5-52e2-9bdf-32e831a7d27a', 'f6cc095a-1c77-562b-8b83-8f0de9104fa3', 'paragraph', $gs${"text":"What this means and why it matters\n\nTo call Jesus Saviour is to admit that we need rescue and to trust Him. This should produce gratitude, humility, and a desire to share the good news with others."}$gs$::jsonb, 2, false, false),
  ('d23aa1df-062f-5929-a1ce-947a07d2d897', 'f6cc095a-1c77-562b-8b83-8f0de9104fa3', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('59c8f19a-5b7f-509b-ae06-3e9bc297ac8e', 'f6cc095a-1c77-562b-8b83-8f0de9104fa3', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('060384fb-93c9-5d06-b641-c52f261cda3c', 'f6cc095a-1c77-562b-8b83-8f0de9104fa3', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Christ as Savior”?"}$gs$::jsonb, 5, true, true),
  ('4e1e0782-6b47-5952-ae98-b20c31760da1', 'f6cc095a-1c77-562b-8b83-8f0de9104fa3', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('67e22c7f-133e-5b3c-9c2a-22e2902ad2ff', 'f6cc095a-1c77-562b-8b83-8f0de9104fa3', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('f20a72c8-984f-5189-bbc5-9f6b0b100614', 'f6cc095a-1c77-562b-8b83-8f0de9104fa3', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “Christ as Savior” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
