insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('8a343019-3437-5426-8000-088b467531e7', '0ea06a78-6bdf-5677-b338-bb9cadee2a62', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$Calling Jesus Lord means recognising His authority. He is not simply a helpful figure whom we consult when convenient; He is the risen King who has the right to direct our lives.$gs$),
  ('d71558a9-ac0c-5e1f-8125-426ed422c166', '0ea06a78-6bdf-5677-b338-bb9cadee2a62', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$Trusting Jesus as Lord does not mean a Christian becomes instantly perfect. It means a new direction: we learn to obey Him, confess when we fail, and place every part of life under His teaching.$gs$),
  ('10208cab-cf4e-5893-b9cb-ade0e19f4bee', '0ea06a78-6bdf-5677-b338-bb9cadee2a62', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
