insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('48f5d1f0-48bf-502a-ab0a-aebd37780e9c', '0ea06a78-6bdf-5677-b338-bb9cadee2a62', 'memory_verse', $gs${"reference":"Romans 10:9","text":"That if you confess with your mouth the Lord Jesus and believe in your heart that God has raised Him from the dead, you will be saved.","translation":""}$gs$::jsonb, 0, true, false),
  ('2ee583cb-7591-5020-98f4-e5ff36074c03', '0ea06a78-6bdf-5677-b338-bb9cadee2a62', 'paragraph', $gs${"text":"Definition and simple explanation\n\nCalling Jesus Lord means recognising His authority. He is not simply a helpful figure whom we consult when convenient; He is the risen King who has the right to direct our lives."}$gs$::jsonb, 1, false, false),
  ('279ececa-ebca-53e7-9c4c-66cf2856e6df', '0ea06a78-6bdf-5677-b338-bb9cadee2a62', 'paragraph', $gs${"text":"What this means and why it matters\n\nTrusting Jesus as Lord does not mean a Christian becomes instantly perfect. It means a new direction: we learn to obey Him, confess when we fail, and place every part of life under His teaching."}$gs$::jsonb, 2, false, false),
  ('59355988-4fc9-59a3-8649-4acc201fdea5', '0ea06a78-6bdf-5677-b338-bb9cadee2a62', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('00e1b2ed-5eef-5805-936e-e81ff96797fc', '0ea06a78-6bdf-5677-b338-bb9cadee2a62', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('1eede445-bcf5-5a42-9007-465c773349c8', '0ea06a78-6bdf-5677-b338-bb9cadee2a62', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Christ as Lord”?"}$gs$::jsonb, 5, true, true),
  ('6b09ac6f-3dc3-59c0-a113-baf8d6ec8a0e', '0ea06a78-6bdf-5677-b338-bb9cadee2a62', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('99a70963-7e0d-54c7-8808-f9bb4c3e822d', '0ea06a78-6bdf-5677-b338-bb9cadee2a62', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('3f64d72e-fc06-5682-a109-587e17c65759', '0ea06a78-6bdf-5677-b338-bb9cadee2a62', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “Christ as Lord” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
