insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('7dff1ec6-89ae-58c4-b5ad-0ec37bbc32c3', 'fca33890-1adc-585c-8875-b15c6761b0a2', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$The Bible promises that Jesus will return. His coming will make His rule visible, bring justice, and complete God’s plan. Christians differ on some details about the timing and sequence of end-time events, but the central promise of His return is clear.$gs$),
  ('84eef6e4-8f15-51ae-9087-dba7bf1a5c8a', 'fca33890-1adc-585c-8875-b15c6761b0a2', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$This hope encourages faithfulness, courage, and holy living. It should not lead to date-setting or fear-driven speculation. We are called to be ready by trusting Christ and living faithfully today.$gs$),
  ('64028b0b-e0e5-5065-9b9c-761121bd2b63', 'fca33890-1adc-585c-8875-b15c6761b0a2', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
