insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('5a9c9aef-e01f-5dc9-8811-a58f4433cf3b', 'ceafd5e0-5294-5176-ba5f-8f63e98bf7b5', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$Worship is responding to God’s worth with reverence, love, gratitude, and obedience. Christians worship Jesus because Scripture presents Him as worthy of honour and praise. Worship includes singing and gathered services, but it also shapes everyday choices.$gs$),
  ('4182f657-0333-56d5-b870-80532fdcc25a', 'ceafd5e0-5294-5176-ba5f-8f63e98bf7b5', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$True worship is not only outward activity. It involves the heart and should lead to a life that honours Christ. We worship because of who Jesus is and what He has done, not to earn His love.$gs$),
  ('263ec82a-2715-50ec-8e2c-a8da914eeb16', 'ceafd5e0-5294-5176-ba5f-8f63e98bf7b5', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
