insert into public.p2p_assignment_questions (id, assignment_id, question, display_order) values
  ('ee03b42a-c544-55df-9722-3fb63a8a5f19', '44f87237-ee52-51fc-8882-bd09d962f34b', $gs$Define the main idea in the lesson “Worshiping Christ Rightly” using simple language.$gs$, 1),
  ('f7c6fc9b-8325-51b1-bb7f-07e655e07e20', '44f87237-ee52-51fc-8882-bd09d962f34b', $gs$What does the key Bible passage teach about God, people, or the Christian life?$gs$, 2),
  ('2de3b493-9032-50d8-8c17-9299e73191ab', '44f87237-ee52-51fc-8882-bd09d962f34b', $gs$Explain why this teaching matters. Give one reason from the lesson.$gs$, 3),
  ('98f77e9d-7980-5271-8677-b9972e15f081', '44f87237-ee52-51fc-8882-bd09d962f34b', $gs$Give one practical example of how someone could respond to this teaching.$gs$, 4)
insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('b717fff6-d66b-5b19-84db-1ba6b658d88d', 'ceafd5e0-5294-5176-ba5f-8f63e98bf7b5', 'memory_verse', $gs${"reference":"Revelation 5:12","text":"Worthy is the Lamb who was slain to receive power and riches and wisdom, and strength and honor and glory and blessing!","translation":""}$gs$::jsonb, 0, true, false),
  ('fa9454f0-74ba-5f1d-b3df-c6c20903850e', 'ceafd5e0-5294-5176-ba5f-8f63e98bf7b5', 'paragraph', $gs${"text":"Definition and simple explanation\n\nWorship is responding to God’s worth with reverence, love, gratitude, and obedience. Christians worship Jesus because Scripture presents Him as worthy of honour and praise. Worship includes singing and gathered services, but it also shapes everyday choices."}$gs$::jsonb, 1, false, false),
  ('2b251079-69d2-5b34-bacd-4c17d968dadf', 'ceafd5e0-5294-5176-ba5f-8f63e98bf7b5', 'paragraph', $gs${"text":"What this means and why it matters\n\nTrue worship is not only outward activity. It involves the heart and should lead to a life that honours Christ. We worship because of who Jesus is and what He has done, not to earn His love."}$gs$::jsonb, 2, false, false),
  ('ef22c7ee-a430-5a63-910d-9de724edf60a', 'ceafd5e0-5294-5176-ba5f-8f63e98bf7b5', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('a78299ac-e7ad-5670-aa88-ac60a3a1ee96', 'ceafd5e0-5294-5176-ba5f-8f63e98bf7b5', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('5f7c6e71-d9e7-52c9-a107-f71a4273b99a', 'ceafd5e0-5294-5176-ba5f-8f63e98bf7b5', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Worshiping Christ Rightly”?"}$gs$::jsonb, 5, true, true),
  ('4316c5b9-f35a-546d-94dd-4a95254a03a6', 'ceafd5e0-5294-5176-ba5f-8f63e98bf7b5', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('6ff15ccf-6d8c-575a-988c-a11c34f23859', 'ceafd5e0-5294-5176-ba5f-8f63e98bf7b5', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('8c46771d-a266-5f1a-a0f2-627e3f0bb018', 'ceafd5e0-5294-5176-ba5f-8f63e98bf7b5', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “Worshiping Christ Rightly” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
