insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('7eb4b001-44e5-52ce-8d27-10c9d692f756', '2d56ae11-0460-5105-a475-bcb7211420d3', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$A disciple is a learner who follows Jesus. Discipleship means listening to His teaching, trusting Him, obeying Him, and becoming more like Him over a lifetime. It is not reserved for pastors or unusually committed Christians; every believer is called to follow Jesus.$gs$),
  ('e5304f1b-49c3-5a4d-8ad4-3dd01ff348f4', '2d56ae11-0460-5105-a475-bcb7211420d3', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$Following Jesus has a cost because His priorities may challenge our comfort, habits, and relationships. Jesus does not call us to earn salvation through effort; He calls those who belong to Him to live out their faith with loyalty and perseverance.$gs$),
  ('85c45a24-aff6-543b-b7b1-f86ca47d071c', '2d56ae11-0460-5105-a475-bcb7211420d3', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
