  ('7239b70b-1517-52f5-b841-b5d15398af27', '2d56ae11-0460-5105-a475-bcb7211420d3', 'paragraph', $gs${"text":"What this means and why it matters\n\nFollowing Jesus has a cost because His priorities may challenge our comfort, habits, and relationships. Jesus does not call us to earn salvation through effort; He calls those who belong to Him to live out their faith with loyalty and perseverance."}$gs$::jsonb, 2, false, false),
  ('1e83e12b-92a7-54e4-a0ce-69f437318521', '2d56ae11-0460-5105-a475-bcb7211420d3', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('b1fb4cdf-317b-55f1-b0e2-6a87b8cc2978', '2d56ae11-0460-5105-a475-bcb7211420d3', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('75dd8b41-27c4-5d37-958b-f190a9787090', '2d56ae11-0460-5105-a475-bcb7211420d3', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Following Christ Wholly”?"}$gs$::jsonb, 5, true, true),
  ('e1f99a13-c6f3-51fc-82c8-98ecc17a714a', '2d56ae11-0460-5105-a475-bcb7211420d3', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('b52182b0-4815-5678-aa31-a8cf62d7714f', '2d56ae11-0460-5105-a475-bcb7211420d3', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('11111266-8ceb-5516-bc91-d2646d6e28f6', '2d56ae11-0460-5105-a475-bcb7211420d3', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “Following Christ Wholly” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
