insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('b35f9dec-0934-5e89-b5dc-2ea0e46a3739', 'f3bd9cc6-f59f-5572-9b2f-9c8140e33314', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$This lesson focuses on A Lifetime of Knowing Christ. Begin by reading the key Bible passage in its full context. Notice who is speaking, who is being addressed, what problem or question is being discussed, and what the passage teaches about God and people. The lesson title gives the subject, but the passage provides the foundation for understanding it.$gs$),
  ('f4e55eb6-b734-579d-a109-239bd41d29d3', 'f3bd9cc6-f59f-5572-9b2f-9c8140e33314', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$The main point is to understand how this teaching connects with the Christian life and the wider message of Scripture. Avoid drawing conclusions from one sentence alone. Compare the passage with other relevant parts of the Bible, ask what a faithful response looks like, and remember that Christian growth is a process of learning to trust and obey God.$gs$),
  ('fc2c6a06-0727-5021-8e83-47ba85d9bb74', 'f3bd9cc6-f59f-5572-9b2f-9c8140e33314', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
