  ('88591e82-3934-5444-b3f2-4c6d2624506e', 'f3bd9cc6-f59f-5572-9b2f-9c8140e33314', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
