  ('3394741e-8284-563c-9ce3-67a840632c9c', 'bc425874-c5cd-5bd2-9039-1dc59b25751a', 'paragraph', $gs${"text":"Definition and simple explanation\n\nThis lesson focuses on The Reality of Sin. Begin by reading the key Bible passage in its full context. Notice who is speaking, who is being addressed, what problem or question is being discussed, and what the passage teaches about God and people. The lesson title gives the subject, but the passage provides the foundation for understanding it."}$gs$::jsonb, 1, false, false),
  ('b7a048d6-0126-5789-a83b-78265df76759', 'bc425874-c5cd-5bd2-9039-1dc59b25751a', 'paragraph', $gs${"text":"What this means and why it matters\n\nThe main point is to understand how this teaching connects with the Christian life and the wider message of Scripture. Avoid drawing conclusions from one sentence alone. Compare the passage with other relevant parts of the Bible, ask what a faithful response looks like, and remember that Christian growth is a process of learning to trust and obey God."}$gs$::jsonb, 2, false, false),
  ('9ce49107-5f90-59ce-921f-a8835a2ebdf4', 'bc425874-c5cd-5bd2-9039-1dc59b25751a', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('38685b99-c359-5184-87ba-1f19f7e2eec2', 'bc425874-c5cd-5bd2-9039-1dc59b25751a', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('0b34b775-1534-5e36-bd1f-8a1f8613a8a0', 'bc425874-c5cd-5bd2-9039-1dc59b25751a', 'reflection_question', $gs${"question":"In your own words, what is the main point of “The Reality of Sin”?"}$gs$::jsonb, 5, true, true),
  ('af1c6227-6973-5e18-861d-314205d41fa8', 'bc425874-c5cd-5bd2-9039-1dc59b25751a', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('f15daa93-1674-5a66-b28f-cda7f8c410a4', 'bc425874-c5cd-5bd2-9039-1dc59b25751a', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('5c2bc865-adca-5525-9af9-dfcdcd1e99e6', 'bc425874-c5cd-5bd2-9039-1dc59b25751a', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “The Reality of Sin” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
