insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('88e4290d-a0b6-5147-8cd5-4edbe47e0608', 'c2c1d3c3-bff1-5d46-adcb-7493774d96d8', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$God’s judgment means that He responds rightly to evil. His anger is not a sudden temper or unfair hostility; it is His holy opposition to sin. Scripture says that people are accountable to Him and that rejecting the Son leaves a person under judgment.$gs$),
  ('0921e49d-2f8c-5190-a491-eff0b60f0692', 'c2c1d3c3-bff1-5d46-adcb-7493774d96d8', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$This truth should make the gospel urgent, but it must never make Christians cruel or self-righteous. We share the warning with humility, remembering that salvation is offered through God’s love in Christ.$gs$),
  ('a70c42b6-6aca-503b-ab5a-f10335921793', 'c2c1d3c3-bff1-5d46-adcb-7493774d96d8', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
