  ('f600e5f9-689b-5ee2-96d2-f7e600edf048', 'c2c1d3c3-bff1-5d46-adcb-7493774d96d8', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
