insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('ed290399-9f04-50ce-bbcb-78539fe2b51e', '4e1ac2a0-b595-5509-a15f-dafef10ddde5', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$Sin is not only a list of wrong actions; it can become a power that enslaves our desires and choices. Jesus said that the one who practises sin is a slave to sin. People may make real choices, but sin distorts what they love and how they use their freedom.$gs$),
  ('18f185a2-55b3-57dc-8030-165dd5bcd123', '4e1ac2a0-b595-5509-a15f-dafef10ddde5', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$Jesus offers freedom from sin’s mastery. This does not mean believers never struggle again. It means Christ begins a new life in which sin is no longer their rightful master, and they learn to live in obedience through His help.$gs$),
  ('d91a954f-1226-57fb-acf5-777963cc0d58', '4e1ac2a0-b595-5509-a15f-dafef10ddde5', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
