insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('dab6a292-b3e1-5f1a-825f-80629db241e8', '4e1ac2a0-b595-5509-a15f-dafef10ddde5', 'memory_verse', $gs${"reference":"Romans 5:8","text":"But God demonstrates His own love toward us, in that while we were still sinners, Christ died for us.","translation":""}$gs$::jsonb, 0, true, false),
  ('dfc27cc4-b217-57cd-a366-71769104f932', '4e1ac2a0-b595-5509-a15f-dafef10ddde5', 'paragraph', $gs${"text":"Definition and simple explanation\n\nSin is not only a list of wrong actions; it can become a power that enslaves our desires and choices. Jesus said that the one who practises sin is a slave to sin. People may make real choices, but sin distorts what they love and how they use their freedom."}$gs$::jsonb, 1, false, false),
  ('efa721ad-e404-5937-b536-cee805e47c96', '4e1ac2a0-b595-5509-a15f-dafef10ddde5', 'paragraph', $gs${"text":"What this means and why it matters\n\nJesus offers freedom from sin’s mastery. This does not mean believers never struggle again. It means Christ begins a new life in which sin is no longer their rightful master, and they learn to live in obedience through His help."}$gs$::jsonb, 2, false, false),
  ('98135926-6871-55ce-aeea-90915e6879a8', '4e1ac2a0-b595-5509-a15f-dafef10ddde5', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('87ca160b-ecf5-5719-a5e4-ae3e580f2f09', '4e1ac2a0-b595-5509-a15f-dafef10ddde5', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader. The Good News of the Gospel"}$gs$::jsonb, 4, false, false),
  ('f746fa9c-86cd-5fa3-9bc1-940b0b691176', '4e1ac2a0-b595-5509-a15f-dafef10ddde5', 'reflection_question', $gs${"question":"In your own words, what is the main point of “The Reality of Our Helplessness”?"}$gs$::jsonb, 5, true, true),
  ('ef836e53-da78-5d45-8df4-ace1e02da53c', '4e1ac2a0-b595-5509-a15f-dafef10ddde5', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('f8372695-aad3-53f4-8ade-3596c25d92a2', '4e1ac2a0-b595-5509-a15f-dafef10ddde5', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('0b4e86bf-2883-5e0e-92fd-0b1acc6ffd68', '4e1ac2a0-b595-5509-a15f-dafef10ddde5', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “The Reality of Our Helplessness” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
