insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('f30ec9f3-ceac-5192-836d-bc7ab83f12fe', 'd6f733d3-6d15-5591-ad2b-9364534ec539', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$Jesus’ death was for us. He took the judgment our sins deserved and gave Himself willingly. This is called substitution: Jesus stood in the place of sinners. His death was not an accident or merely an example of courage; it was central to God’s saving plan.$gs$),
  ('f099bbb8-6d46-588c-b400-8522fa405ba8', 'd6f733d3-6d15-5591-ad2b-9364534ec539', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$The cross shows both how serious sin is and how great God’s love is. We do not earn this gift. We receive it by faith, trusting what Jesus has done rather than relying on our own goodness.$gs$),
  ('830d76e5-3695-503b-9c30-10bf5315d436', 'd6f733d3-6d15-5591-ad2b-9364534ec539', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
