  ('01b0347a-c48b-524a-a9c0-7dd1bb21b10e', 'd6f733d3-6d15-5591-ad2b-9364534ec539', 'paragraph', $gs${"text":"What this means and why it matters\n\nThe cross shows both how serious sin is and how great God’s love is. We do not earn this gift. We receive it by faith, trusting what Jesus has done rather than relying on our own goodness."}$gs$::jsonb, 2, false, false),
  ('18cd496a-7fe8-506c-9971-c0ebbc960cd9', 'd6f733d3-6d15-5591-ad2b-9364534ec539', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('5195144d-cd98-5b56-bde5-0db6db0d2ae8', 'd6f733d3-6d15-5591-ad2b-9364534ec539', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('4203139f-d035-5ed3-a94e-5975c28d95e5', 'd6f733d3-6d15-5591-ad2b-9364534ec539', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Christ’s Death for Our Sins”?"}$gs$::jsonb, 5, true, true),
  ('89ce3ce4-2551-5178-8837-d41e8c0712f1', 'd6f733d3-6d15-5591-ad2b-9364534ec539', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('ea141e67-7489-50c2-b33a-74d69c52c976', 'd6f733d3-6d15-5591-ad2b-9364534ec539', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('2939cd92-725b-54c1-a703-bbbdfd15865b', 'd6f733d3-6d15-5591-ad2b-9364534ec539', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “Christ’s Death for Our Sins” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
insert into public.p2p_lessons (id, module_id, title, subtitle, order_index, status, estimated_minutes, published_at, version)
insert into public.p2p_scriptures (id, lesson_id, reference, verse, display_order)
insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('4798ae0e-6355-5a85-b0dc-dbb7d491d2a3', '2302c20b-d6fa-5ca3-a270-75ae6d19dd67', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$The resurrection means that Jesus physically rose from the dead. The Christian faith is not based only on the memory of a wise teacher or on the idea that His influence continued. The apostles proclaimed that the risen Jesus was seen by witnesses.$gs$),
  ('f8890e19-6e6f-5611-8dd8-9c227d209644', '2302c20b-d6fa-5ca3-a270-75ae6d19dd67', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$The resurrection shows that death did not defeat Jesus and that His saving work is accepted. It gives believers hope that death is not the end and that those who belong to Christ will also be raised.$gs$),
  ('a0805b7d-8a81-5f07-9586-744df2d810cc', '2302c20b-d6fa-5ca3-a270-75ae6d19dd67', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
