insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('4e30d623-398b-5dd8-830c-5a39e917f111', '2302c20b-d6fa-5ca3-a270-75ae6d19dd67', 'memory_verse', $gs${"reference":"Romans 4:25","text":"Who was delivered up because of our offenses, and was raised because of our justification.","translation":""}$gs$::jsonb, 0, true, false),
  ('a6d892fe-9fbe-5bfc-9c35-6604a5d0ae1d', '2302c20b-d6fa-5ca3-a270-75ae6d19dd67', 'paragraph', $gs${"text":"Definition and simple explanation\n\nThe resurrection means that Jesus physically rose from the dead. The Christian faith is not based only on the memory of a wise teacher or on the idea that His influence continued. The apostles proclaimed that the risen Jesus was seen by witnesses."}$gs$::jsonb, 1, false, false),
  ('9bcf9fb2-8b67-595d-a887-ffadcb71d3ab', '2302c20b-d6fa-5ca3-a270-75ae6d19dd67', 'paragraph', $gs${"text":"What this means and why it matters\n\nThe resurrection shows that death did not defeat Jesus and that His saving work is accepted. It gives believers hope that death is not the end and that those who belong to Christ will also be raised."}$gs$::jsonb, 2, false, false),
  ('8be70770-9a1f-5905-bae9-d99c2a2f121c', '2302c20b-d6fa-5ca3-a270-75ae6d19dd67', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('38bfad74-217d-5451-8024-bbea1861cf62', '2302c20b-d6fa-5ca3-a270-75ae6d19dd67', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('8517b340-7c0e-5bcc-a66a-df85cd0374b0', '2302c20b-d6fa-5ca3-a270-75ae6d19dd67', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Christ’s Resurrection for Our Justification”?"}$gs$::jsonb, 5, true, true),
  ('796df34a-9edc-576b-b4cf-af690f0d9dc1', '2302c20b-d6fa-5ca3-a270-75ae6d19dd67', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('ccfd250b-4217-5308-9c53-75cfcf755fa5', '2302c20b-d6fa-5ca3-a270-75ae6d19dd67', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('f0df0cf6-c0f1-551d-b99e-7dc3487b34f1', '2302c20b-d6fa-5ca3-a270-75ae6d19dd67', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “Christ’s Resurrection for Our Justification” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
