insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('f97c66d1-3106-5415-9889-c513fc411d32', '87b65ef6-88ef-556c-8f5b-c6997963aa3b', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$This lesson focuses on Grace: The Gift We Could Not Earn. Begin by reading the key Bible passage in its full context. Notice who is speaking, who is being addressed, what problem or question is being discussed, and what the passage teaches about God and people. The lesson title gives the subject, but the passage provides the foundation for understanding it.$gs$),
  ('25e109bf-55d5-5f7b-a08e-8a23a4fa1566', '87b65ef6-88ef-556c-8f5b-c6997963aa3b', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$The main point is to understand how this teaching connects with the Christian life and the wider message of Scripture. Avoid drawing conclusions from one sentence alone. Compare the passage with other relevant parts of the Bible, ask what a faithful response looks like, and remember that Christian growth is a process of learning to trust and obey God.$gs$),
  ('cc93c7ea-233d-54a0-b3d7-14980ccd9bab', '87b65ef6-88ef-556c-8f5b-c6997963aa3b', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
