  ('746f91c5-ebbb-5073-84d9-a12633fcddf6', '87b65ef6-88ef-556c-8f5b-c6997963aa3b', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('3b6e162a-eccd-5548-addc-973370acc77e', '87b65ef6-88ef-556c-8f5b-c6997963aa3b', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader. The Gospel Is for Everyone"}$gs$::jsonb, 4, false, false),
  ('e6d07d84-c652-5dc7-8dc7-7c5be28284b6', '87b65ef6-88ef-556c-8f5b-c6997963aa3b', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Grace: The Gift We Could Not Earn”?"}$gs$::jsonb, 5, true, true),
  ('93b2978a-9457-5521-92e9-b22102a14cf6', '87b65ef6-88ef-556c-8f5b-c6997963aa3b', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('9697598e-d1b1-51e8-8466-0e73344e5856', '87b65ef6-88ef-556c-8f5b-c6997963aa3b', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('1276379d-0b41-565f-ba77-f3399cb55837', '87b65ef6-88ef-556c-8f5b-c6997963aa3b', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “Grace: The Gift We Could Not Earn” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
