insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('1f7613bb-dcc5-56b4-8533-4df00135e746', '721b800e-00bd-5bc4-8de9-eeb91da25aca', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$The gospel means good news: God saves sinners through Jesus Christ. The message includes the truth that all people have sinned, Jesus died for our sins, He was raised from the dead, and forgiveness and new life are offered by grace to everyone who trusts Him.$gs$),
  ('729d6c33-3589-5b8c-8ce6-450d2c4f74a5', '721b800e-00bd-5bc4-8de9-eeb91da25aca', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$The gospel must not be changed into a message that people earn salvation by good behaviour, money, religious performance, or human achievement. Good works matter as the fruit of faith, but Christ—not our performance—is the centre of the good news.$gs$),
  ('6d03ef17-9ce3-511e-b4bf-43ee0835213d', '721b800e-00bd-5bc4-8de9-eeb91da25aca', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
