insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('fdf69c9f-8107-58ad-bbea-0041bb9dc597', '721b800e-00bd-5bc4-8de9-eeb91da25aca', 'memory_verse', $gs${"reference":"Romans 10:12","text":"For there is no difference between Jew and Greek, for the same Lord over all is rich to all who call upon Him.","translation":""}$gs$::jsonb, 0, true, false),
  ('b18143d0-2b4a-5e9f-9c87-ce702c3c788d', '721b800e-00bd-5bc4-8de9-eeb91da25aca', 'paragraph', $gs${"text":"Definition and simple explanation\n\nThe gospel means good news: God saves sinners through Jesus Christ. The message includes the truth that all people have sinned, Jesus died for our sins, He was raised from the dead, and forgiveness and new life are offered by grace to everyone who trusts Him."}$gs$::jsonb, 1, false, false),
  ('8e57dd7a-50f7-5455-babd-81c4e9b2f8a2', '721b800e-00bd-5bc4-8de9-eeb91da25aca', 'paragraph', $gs${"text":"What this means and why it matters\n\nThe gospel must not be changed into a message that people earn salvation by good behaviour, money, religious performance, or human achievement. Good works matter as the fruit of faith, but Christ—not our performance—is the centre of the good news."}$gs$::jsonb, 2, false, false),
  ('746c6346-8772-54e0-9df9-72fe063eb35a', '721b800e-00bd-5bc4-8de9-eeb91da25aca', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('8e41ba0d-681a-526a-99f3-167bb86a7a4c', '721b800e-00bd-5bc4-8de9-eeb91da25aca', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('a4fd6c8a-6465-5c83-b213-4e15c21f1026', '721b800e-00bd-5bc4-8de9-eeb91da25aca', 'reflection_question', $gs${"question":"In your own words, what is the main point of “The Gospel Levels All People”?"}$gs$::jsonb, 5, true, true),
  ('a542090a-e8c7-52f6-ba0e-da1047fe8918', '721b800e-00bd-5bc4-8de9-eeb91da25aca', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('83389af9-d5c0-5b30-946d-7befa571920e', '721b800e-00bd-5bc4-8de9-eeb91da25aca', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('464ace9c-0cf3-5dd9-84f4-7b5e61875408', '721b800e-00bd-5bc4-8de9-eeb91da25aca', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “The Gospel Levels All People” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
