insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('994e9789-cce8-5824-be32-f1d3166c259f', '893ed61e-a2d4-5b7a-859a-1ca23d5ed3ba', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$The gospel means good news: God saves sinners through Jesus Christ. The message includes the truth that all people have sinned, Jesus died for our sins, He was raised from the dead, and forgiveness and new life are offered by grace to everyone who trusts Him.$gs$),
  ('6b15d797-9259-5465-8b1f-54af06d6965d', '893ed61e-a2d4-5b7a-859a-1ca23d5ed3ba', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$The gospel must not be changed into a message that people earn salvation by good behaviour, money, religious performance, or human achievement. Good works matter as the fruit of faith, but Christ—not our performance—is the centre of the good news.$gs$),
  ('a0e99957-a57b-5101-835b-c67147a85659', '893ed61e-a2d4-5b7a-859a-1ca23d5ed3ba', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
insert into public.p2p_reflection_questions (id, lesson_id, question, display_order) values
  ('6c563494-a325-5a38-8fd4-dd2aea70a0d6', '893ed61e-a2d4-5b7a-859a-1ca23d5ed3ba', $gs$In your own words, what is the main point of “A Lifetime of Gospel Centrality”?$gs$, 1),
  ('89c8e555-d845-5a48-b26f-073014e5c107', '893ed61e-a2d4-5b7a-859a-1ca23d5ed3ba', $gs$What part of this teaching is easiest for you to understand, and what part would you like to discuss further?$gs$, 2),
  ('dd33c55e-325e-586e-bb64-06554bcdc0ce', '893ed61e-a2d4-5b7a-859a-1ca23d5ed3ba', $gs$How could this truth shape one attitude or action in your life this week?$gs$, 3)
insert into public.p2p_assignments (id, lesson_id, title, instructions)
insert into public.p2p_assignment_questions (id, assignment_id, question, display_order) values
  ('ea93cff1-7341-5325-bc96-a4964604b031', 'b0c76031-8160-5da7-b147-a24b4a08f4ce', $gs$Define the main idea in the lesson “A Lifetime of Gospel Centrality” using simple language.$gs$, 1),
  ('5901d5ef-41b5-5e02-a9c4-925bf09d12a9', 'b0c76031-8160-5da7-b147-a24b4a08f4ce', $gs$What does the key Bible passage teach about God, people, or the Christian life?$gs$, 2),
  ('bc3503e3-959d-5704-a13e-b2d6a7f53b5f', 'b0c76031-8160-5da7-b147-a24b4a08f4ce', $gs$Explain why this teaching matters. Give one reason from the lesson.$gs$, 3),
  ('bcbc7f48-2e24-54bf-a946-4d83998b8b47', 'b0c76031-8160-5da7-b147-a24b4a08f4ce', $gs$Give one practical example of how someone could respond to this teaching.$gs$, 4)
insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('061cc810-a78f-5866-a101-079b3d046f6d', '893ed61e-a2d4-5b7a-859a-1ca23d5ed3ba', 'memory_verse', $gs${"reference":"Romans 1:16","text":"For I am not ashamed of the gospel of Christ, for it is the power of God to salvation.","translation":""}$gs$::jsonb, 0, true, false),
  ('44d8f869-612d-5706-acdf-d9e1ea4f11d8', '893ed61e-a2d4-5b7a-859a-1ca23d5ed3ba', 'paragraph', $gs${"text":"Definition and simple explanation\n\nThe gospel means good news: God saves sinners through Jesus Christ. The message includes the truth that all people have sinned, Jesus died for our sins, He was raised from the dead, and forgiveness and new life are offered by grace to everyone who trusts Him."}$gs$::jsonb, 1, false, false),
  ('f6fb8d08-7907-5f28-b2ef-4e39381c1b67', '893ed61e-a2d4-5b7a-859a-1ca23d5ed3ba', 'paragraph', $gs${"text":"What this means and why it matters\n\nThe gospel must not be changed into a message that people earn salvation by good behaviour, money, religious performance, or human achievement. Good works matter as the fruit of faith, but Christ—not our performance—is the centre of the good news."}$gs$::jsonb, 2, false, false),
  ('ba6d8000-b570-55d1-be39-7912cb45b9cf', '893ed61e-a2d4-5b7a-859a-1ca23d5ed3ba', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('6e186588-f452-5f7a-992d-45773502fc9e', '893ed61e-a2d4-5b7a-859a-1ca23d5ed3ba', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('135be575-b0c9-5c8a-ba7d-9cbe5df02ed1', '893ed61e-a2d4-5b7a-859a-1ca23d5ed3ba', 'reflection_question', $gs${"question":"In your own words, what is the main point of “A Lifetime of Gospel Centrality”?"}$gs$::jsonb, 5, true, true),
  ('e29e741d-33ad-5aec-9310-1055fd2f5f02', '893ed61e-a2d4-5b7a-859a-1ca23d5ed3ba', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('e16d9f0d-4e8c-5ef5-90cb-5f556d6734f4', '893ed61e-a2d4-5b7a-859a-1ca23d5ed3ba', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('1adaed91-b3cb-52b9-bc8a-5009b17f789c', '893ed61e-a2d4-5b7a-859a-1ca23d5ed3ba', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “A Lifetime of Gospel Centrality” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
