insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('7d587497-b450-542a-8f63-bc6a8e8fa22b', '4cc15322-3687-5aaa-a1d6-03f2648dec4d', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$Repentance means turning away from sin and turning toward God. It includes a change of mind and heart that leads to a change in direction. It is more than feeling sorry because we were caught or because sin caused painful consequences.$gs$),
  ('1be19a76-8434-5c77-8ad3-31209bc8084e', '4cc15322-3687-5aaa-a1d6-03f2648dec4d', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$Godly sorrow recognises that sin is wrong before God and leads us to seek His mercy and change. Repentance does not mean we make ourselves worthy before coming to God; it is part of our response to His grace.$gs$),
  ('9fbb63a9-7b0f-5ca6-9f04-957390afd4c9', '4cc15322-3687-5aaa-a1d6-03f2648dec4d', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
