  ('a876064f-14c7-5c78-ad38-a1e0e2b0c386', '4cc15322-3687-5aaa-a1d6-03f2648dec4d', 'paragraph', $gs${"text":"What this means and why it matters\n\nGodly sorrow recognises that sin is wrong before God and leads us to seek His mercy and change. Repentance does not mean we make ourselves worthy before coming to God; it is part of our response to His grace."}$gs$::jsonb, 2, false, false),
  ('b1be494b-a004-5871-b1d0-e5e7b2fcd26a', '4cc15322-3687-5aaa-a1d6-03f2648dec4d', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('e877f55c-3a5c-559e-ab73-89b20a725ddf', '4cc15322-3687-5aaa-a1d6-03f2648dec4d', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('2b553968-c660-59ea-b5b7-4db618b5eb6e', '4cc15322-3687-5aaa-a1d6-03f2648dec4d', 'reflection_question', $gs${"question":"In your own words, what is the main point of “What Genuine Repentance Involves”?"}$gs$::jsonb, 5, true, true),
  ('59827566-2500-5149-9cec-e38b3895136f', '4cc15322-3687-5aaa-a1d6-03f2648dec4d', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('84d96b3e-374c-5967-ab84-d2dffdc9539f', '4cc15322-3687-5aaa-a1d6-03f2648dec4d', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('295b960b-d501-52ea-a870-3dc8b7969756', '4cc15322-3687-5aaa-a1d6-03f2648dec4d', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “What Genuine Repentance Involves” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
