  ('405483ed-1b4b-5270-8eba-a15688ad8ce1', '8b45b631-1b83-59a7-b274-6f1ab0857d7d', 'memory_verse', $gs${"reference":"Acts 11:18","text":"Then to the Gentiles also God has granted repentance to life.","translation":""}$gs$::jsonb, 0, true, false),
  ('746e50a9-6f2d-5946-8ec9-02e2b8a10e6d', '8b45b631-1b83-59a7-b274-6f1ab0857d7d', 'paragraph', $gs${"text":"Definition and simple explanation\n\nRepentance means turning away from sin and turning toward God. It includes a change of mind and heart that leads to a change in direction. It is more than feeling sorry because we were caught or because sin caused painful consequences."}$gs$::jsonb, 1, false, false),
