  ('3c5b59d3-2d7f-5687-8c4c-26ba6f43223d', '8b45b631-1b83-59a7-b274-6f1ab0857d7d', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('60f99f5b-c74d-557f-8acf-8014692d0afc', '8b45b631-1b83-59a7-b274-6f1ab0857d7d', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('4d1ad6f1-1823-5ec8-8884-d2a14a45220e', '8b45b631-1b83-59a7-b274-6f1ab0857d7d', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Repentance Is a Gift, Not Just a Decision”?"}$gs$::jsonb, 5, true, true),
  ('9eb94c35-8c13-579b-b6d3-f749ea740700', '8b45b631-1b83-59a7-b274-6f1ab0857d7d', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
