insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('fd11fc7a-a13f-5cfd-b69c-d17064ed9430', '243e0d4a-413a-50a4-bd95-631b5906c8f9', 'memory_verse', $gs${"reference":"2 Corinthians 7:10","text":"For godly sorrow produces repentance leading to salvation, not to be regretted; but the sorrow of the world produces death.","translation":""}$gs$::jsonb, 0, true, false),
  ('205ce03d-faa0-5385-b908-6d6c4ab64ef0', '243e0d4a-413a-50a4-bd95-631b5906c8f9', 'paragraph', $gs${"text":"Definition and simple explanation\n\nRepentance means turning away from sin and turning toward God. It includes a change of mind and heart that leads to a change in direction. It is more than feeling sorry because we were caught or because sin caused painful consequences."}$gs$::jsonb, 1, false, false),
  ('8c6638a3-e575-59a3-9f94-723ec9bea9f3', '243e0d4a-413a-50a4-bd95-631b5906c8f9', 'paragraph', $gs${"text":"What this means and why it matters\n\nGodly sorrow recognises that sin is wrong before God and leads us to seek His mercy and change. Repentance does not mean we make ourselves worthy before coming to God; it is part of our response to His grace."}$gs$::jsonb, 2, false, false),
  ('8dfc4dce-b390-5cc4-9495-2bfa52c3c4c8', '243e0d4a-413a-50a4-bd95-631b5906c8f9', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('69acbcae-1ee8-5411-9644-ed7e1ac1a71e', '243e0d4a-413a-50a4-bd95-631b5906c8f9', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader. Faith: Trusting in Christ"}$gs$::jsonb, 4, false, false),
  ('7330894d-6a04-525d-a906-b5e73614dbc2', '243e0d4a-413a-50a4-bd95-631b5906c8f9', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Godly Sorrow Versus Worldly Sorrow”?"}$gs$::jsonb, 5, true, true),
  ('24c4789b-961c-52cf-92ec-a423c044b3e4', '243e0d4a-413a-50a4-bd95-631b5906c8f9', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('d7bfb620-31cf-5806-a742-100bac190237', '243e0d4a-413a-50a4-bd95-631b5906c8f9', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('35818be4-db01-5343-a155-1e8a03be586e', '243e0d4a-413a-50a4-bd95-631b5906c8f9', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “Godly Sorrow Versus Worldly Sorrow” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
