insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('8641fdc7-00d4-5853-8806-98b5bf489597', '0c3274c7-939c-5dac-baeb-f0d230bd52df', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$Saving faith is trusting in Jesus Christ—who He is and what He has done for sinners. It is more than knowing facts or agreeing that Christianity is true. It means relying on Christ rather than relying on our own efforts to make us right with God.$gs$),
  ('6e7ce22b-a743-5f88-8dda-b249c7d5b28e', '0c3274c7-939c-5dac-baeb-f0d230bd52df', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$Faith does not become valuable because it is strong or impressive. Its value is in the trustworthy person it rests on: Jesus. Good works follow genuine faith as its fruit, but they are not an additional payment for salvation.$gs$),
  ('21b0f4fe-ebfe-5339-b5b5-44110f370836', '0c3274c7-939c-5dac-baeb-f0d230bd52df', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
