  ('fda10622-4acd-57c7-9e63-25759f4a1f38', '1f1eabc9-71db-519d-b0b3-6953ba8c4e03', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$Calling Jesus Lord means recognising His authority. He is not simply a helpful figure whom we consult when convenient; He is the risen King who has the right to direct our lives.$gs$),
  ('738f096e-f509-5172-bacb-c3ba47442825', '1f1eabc9-71db-519d-b0b3-6953ba8c4e03', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$Trusting Jesus as Lord does not mean a Christian becomes instantly perfect. It means a new direction: we learn to obey Him, confess when we fail, and place every part of life under His teaching.$gs$),
  ('ef91ee65-9fa0-50bc-a883-9e5558f95e94', '1f1eabc9-71db-519d-b0b3-6953ba8c4e03', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
insert into public.p2p_reflection_questions (id, lesson_id, question, display_order) values
  ('dddb40f9-d57b-5961-a176-73d8ae1201be', '1f1eabc9-71db-519d-b0b3-6953ba8c4e03', $gs$In your own words, what is the main point of “Confessing Christ as Lord”?$gs$, 1),
  ('237886e0-2738-5e6a-936c-a33cc2ab1a82', '1f1eabc9-71db-519d-b0b3-6953ba8c4e03', $gs$What part of this teaching is easiest for you to understand, and what part would you like to discuss further?$gs$, 2),
  ('8951efc5-1855-59be-b730-1bb5cc776306', '1f1eabc9-71db-519d-b0b3-6953ba8c4e03', $gs$How could this truth shape one attitude or action in your life this week?$gs$, 3)
insert into public.p2p_assignments (id, lesson_id, title, instructions)
insert into public.p2p_assignment_questions (id, assignment_id, question, display_order) values
  ('069237e9-1a06-5b65-a3f1-4440ce87b5d0', '52ae4b8d-861b-5f4b-b54a-da13ea9f2ff4', $gs$Define the main idea in the lesson “Confessing Christ as Lord” using simple language.$gs$, 1),
  ('8fc6d03f-668a-5402-9bf2-398fb670e13a', '52ae4b8d-861b-5f4b-b54a-da13ea9f2ff4', $gs$What does the key Bible passage teach about God, people, or the Christian life?$gs$, 2),
  ('f9691cc9-1acc-5791-a427-5e6b40de7e6d', '52ae4b8d-861b-5f4b-b54a-da13ea9f2ff4', $gs$Explain why this teaching matters. Give one reason from the lesson.$gs$, 3),
  ('07b848f0-514c-520f-b5a9-c413eb983ae7', '52ae4b8d-861b-5f4b-b54a-da13ea9f2ff4', $gs$Give one practical example of how someone could respond to this teaching.$gs$, 4)
insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('812541e4-8860-5f2d-aa2f-02c7088974ea', '1f1eabc9-71db-519d-b0b3-6953ba8c4e03', 'memory_verse', $gs${"reference":"Romans 10:9","text":"That if you confess with your mouth the Lord Jesus and believe in your heart that God has raised Him from the dead, you will be saved.","translation":""}$gs$::jsonb, 0, true, false),
  ('63b83442-d12c-54b5-a322-24a77b5bf7bf', '1f1eabc9-71db-519d-b0b3-6953ba8c4e03', 'paragraph', $gs${"text":"Definition and simple explanation\n\nCalling Jesus Lord means recognising His authority. He is not simply a helpful figure whom we consult when convenient; He is the risen King who has the right to direct our lives."}$gs$::jsonb, 1, false, false),
  ('69033532-177c-5624-89c8-9add71b59e4b', '1f1eabc9-71db-519d-b0b3-6953ba8c4e03', 'paragraph', $gs${"text":"What this means and why it matters\n\nTrusting Jesus as Lord does not mean a Christian becomes instantly perfect. It means a new direction: we learn to obey Him, confess when we fail, and place every part of life under His teaching."}$gs$::jsonb, 2, false, false),
  ('a63f58da-fc96-5648-bae2-6209e293d05a', '1f1eabc9-71db-519d-b0b3-6953ba8c4e03', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('bff1d9a9-8896-5d49-8c87-7a6f5c97b9b2', '1f1eabc9-71db-519d-b0b3-6953ba8c4e03', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('c3646fa3-7f2c-5170-969d-1718901a1749', '1f1eabc9-71db-519d-b0b3-6953ba8c4e03', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Confessing Christ as Lord”?"}$gs$::jsonb, 5, true, true),
  ('42ff5d6d-f804-54fb-97e2-e00e2092ba97', '1f1eabc9-71db-519d-b0b3-6953ba8c4e03', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('8c7e9041-7e37-5bc5-aaa1-448b7b3b7d5e', '1f1eabc9-71db-519d-b0b3-6953ba8c4e03', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('b2ffa5f3-afe0-5760-98c2-dfc0299a17fe', '1f1eabc9-71db-519d-b0b3-6953ba8c4e03', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “Confessing Christ as Lord” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
