insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('cc058b28-2bb1-5d2a-b806-46d189fac590', 'bc52902f-c1d7-52dd-9604-d320ccd22dae', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$This lesson focuses on Surrendering Control of Your Life. Begin by reading the key Bible passage in its full context. Notice who is speaking, who is being addressed, what problem or question is being discussed, and what the passage teaches about God and people. The lesson title gives the subject, but the passage provides the foundation for understanding it.$gs$),
  ('f42fc815-9eaa-523d-b6a5-bdfef989a977', 'bc52902f-c1d7-52dd-9604-d320ccd22dae', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$The main point is to understand how this teaching connects with the Christian life and the wider message of Scripture. Avoid drawing conclusions from one sentence alone. Compare the passage with other relevant parts of the Bible, ask what a faithful response looks like, and remember that Christian growth is a process of learning to trust and obey God.$gs$),
  ('56bbf1d1-e14d-5726-911c-d6d9d981c9bc', 'bc52902f-c1d7-52dd-9604-d320ccd22dae', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
