insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('dd4c3774-5f21-500c-802d-08b1853e634c', 'bc52902f-c1d7-52dd-9604-d320ccd22dae', 'memory_verse', $gs${"reference":"Romans 12:1","text":"I beseech you therefore, brethren, by the mercies of God, that you present your bodies a living sacrifice.","translation":""}$gs$::jsonb, 0, true, false),
  ('ec435393-6dfb-52e9-93fa-182899c261c6', 'bc52902f-c1d7-52dd-9604-d320ccd22dae', 'paragraph', $gs${"text":"Definition and simple explanation\n\nThis lesson focuses on Surrendering Control of Your Life. Begin by reading the key Bible passage in its full context. Notice who is speaking, who is being addressed, what problem or question is being discussed, and what the passage teaches about God and people. The lesson title gives the subject, but the passage provides the foundation for understanding it."}$gs$::jsonb, 1, false, false),
  ('fa2de90e-e5cb-5ddb-95b0-4a5d0d3bcc12', 'bc52902f-c1d7-52dd-9604-d320ccd22dae', 'paragraph', $gs${"text":"What this means and why it matters\n\nThe main point is to understand how this teaching connects with the Christian life and the wider message of Scripture. Avoid drawing conclusions from one sentence alone. Compare the passage with other relevant parts of the Bible, ask what a faithful response looks like, and remember that Christian growth is a process of learning to trust and obey God."}$gs$::jsonb, 2, false, false),
  ('57a0ab3c-0273-59dc-98ae-420e7fbe8517', 'bc52902f-c1d7-52dd-9604-d320ccd22dae', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('eec7a22a-bbd4-53ca-85e9-6e95e3b8e865', 'bc52902f-c1d7-52dd-9604-d320ccd22dae', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('cbd9ac2b-c3ce-51dd-aa62-fbbb51fc5a6b', 'bc52902f-c1d7-52dd-9604-d320ccd22dae', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Surrendering Control of Your Life”?"}$gs$::jsonb, 5, true, true),
  ('b302cad0-78e4-57bf-99f6-70596d162bd9', 'bc52902f-c1d7-52dd-9604-d320ccd22dae', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('058a82fd-bbca-5cb0-aa9b-51a30410584d', 'bc52902f-c1d7-52dd-9604-d320ccd22dae', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('9e1c5b54-8ccc-574a-bf7a-47c11de9af86', 'bc52902f-c1d7-52dd-9604-d320ccd22dae', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “Surrendering Control of Your Life” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
