insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('cc914510-82fc-5002-8052-4905b4edcb2b', '38b0b99b-4145-5817-9ff1-90cd77fef653', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$A disciple is a learner who follows Jesus. Discipleship means listening to His teaching, trusting Him, obeying Him, and becoming more like Him over a lifetime. It is not reserved for pastors or unusually committed Christians; every believer is called to follow Jesus.$gs$),
  ('bf5ae3da-b7ce-539e-88db-d0622d432d69', '38b0b99b-4145-5817-9ff1-90cd77fef653', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$Following Jesus has a cost because His priorities may challenge our comfort, habits, and relationships. Jesus does not call us to earn salvation through effort; He calls those who belong to Him to live out their faith with loyalty and perseverance.$gs$),
  ('5c7ba305-d57f-5a38-86e8-4d95a6777872', '38b0b99b-4145-5817-9ff1-90cd77fef653', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
