insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('e4f44da2-cd22-5316-b1a2-4d12fa3329d8', '38b0b99b-4145-5817-9ff1-90cd77fef653', 'memory_verse', $gs${"reference":"Luke 14:28","text":"For which of you, intending to build a tower, does not sit down first and count the cost?","translation":""}$gs$::jsonb, 0, true, false),
  ('c6a95cbe-6149-538f-bd61-e27ee28adb4b', '38b0b99b-4145-5817-9ff1-90cd77fef653', 'paragraph', $gs${"text":"Definition and simple explanation\n\nA disciple is a learner who follows Jesus. Discipleship means listening to His teaching, trusting Him, obeying Him, and becoming more like Him over a lifetime. It is not reserved for pastors or unusually committed Christians; every believer is called to follow Jesus."}$gs$::jsonb, 1, false, false),
  ('ec1ca6a6-3216-5c79-85a4-b92ad742f446', '38b0b99b-4145-5817-9ff1-90cd77fef653', 'paragraph', $gs${"text":"What this means and why it matters\n\nFollowing Jesus has a cost because His priorities may challenge our comfort, habits, and relationships. Jesus does not call us to earn salvation through effort; He calls those who belong to Him to live out their faith with loyalty and perseverance."}$gs$::jsonb, 2, false, false),
  ('d30b6d92-0524-5829-b80d-d613489b7a32', '38b0b99b-4145-5817-9ff1-90cd77fef653', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('8f632ce9-3e6a-5026-8035-36aa8f5b5d0e', '38b0b99b-4145-5817-9ff1-90cd77fef653', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader. Making It Real"}$gs$::jsonb, 4, false, false),
  ('fdbd988f-1872-57be-a516-6e7bee21e7ff', '38b0b99b-4145-5817-9ff1-90cd77fef653', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Counting the Cost of Following Christ”?"}$gs$::jsonb, 5, true, true),
  ('d0ad2d49-4de3-55bb-8bc3-221e95e73c03', '38b0b99b-4145-5817-9ff1-90cd77fef653', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('9c6fe1bb-7149-5ed2-b68f-c3f1c6c37274', '38b0b99b-4145-5817-9ff1-90cd77fef653', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('a59dcfbd-7114-5977-b9ce-06a2a9db4fea', '38b0b99b-4145-5817-9ff1-90cd77fef653', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “Counting the Cost of Following Christ” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
