insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('854ff55a-2668-56b8-8cb2-c2824a68e2a4', 'bf438b43-7905-5b94-b3c0-291bd3e2b9cb', 'memory_verse', $gs${"reference":"Romans 10:13","text":"For ‘whoever calls on the name of the Lord shall be saved.’","translation":""}$gs$::jsonb, 0, true, false),
  ('4ebe7ae0-1ce9-5df7-892f-57ff22b3b21b', 'bf438b43-7905-5b94-b3c0-291bd3e2b9cb', 'paragraph', $gs${"text":"Definition and simple explanation\n\nThis lesson focuses on Praying to Receive Christ. Begin by reading the key Bible passage in its full context. Notice who is speaking, who is being addressed, what problem or question is being discussed, and what the passage teaches about God and people. The lesson title gives the subject, but the passage provides the foundation for understanding it."}$gs$::jsonb, 1, false, false),
  ('54164868-d58a-5be0-96a6-4d830edb091f', 'bf438b43-7905-5b94-b3c0-291bd3e2b9cb', 'paragraph', $gs${"text":"What this means and why it matters\n\nThe main point is to understand how this teaching connects with the Christian life and the wider message of Scripture. Avoid drawing conclusions from one sentence alone. Compare the passage with other relevant parts of the Bible, ask what a faithful response looks like, and remember that Christian growth is a process of learning to trust and obey God."}$gs$::jsonb, 2, false, false),
  ('8063d2bc-37a8-519e-a5b5-10ca44e6e297', 'bf438b43-7905-5b94-b3c0-291bd3e2b9cb', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('90c20df4-c3fc-5722-830f-c962618785dc', 'bf438b43-7905-5b94-b3c0-291bd3e2b9cb', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('8812d298-8c5a-544b-bead-8f4328bc8991', 'bf438b43-7905-5b94-b3c0-291bd3e2b9cb', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Praying to Receive Christ”?"}$gs$::jsonb, 5, true, true),
  ('a1c354f3-4728-575b-9250-a2d2fb1324f1', 'bf438b43-7905-5b94-b3c0-291bd3e2b9cb', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('59540f8c-9479-5a12-b05a-b762df6a5328', 'bf438b43-7905-5b94-b3c0-291bd3e2b9cb', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('b7a85f78-9115-59ce-a21a-a77c03fe1033', 'bf438b43-7905-5b94-b3c0-291bd3e2b9cb', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “Praying to Receive Christ” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
