insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('4bb76d9b-634c-5033-8d48-734420a40530', '3fb22436-f60b-51f6-b035-3bb3a37ffa4e', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$Assurance is confidence that God has given eternal life to those who trust in Christ. Its foundation is God’s promise and Jesus’ finished work, not the changing strength of our emotions. Feelings can rise and fall, especially during stress or hardship.$gs$),
  ('ff6ca621-cd21-59e9-85d2-1c1ce27724cf', '3fb22436-f60b-51f6-b035-3bb3a37ffa4e', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$The New Testament also describes changes that accompany genuine faith, such as growing love, obedience, and the Spirit’s fruit. These are signs of God’s work, not a way to earn His acceptance. Persistent distress or serious questions can be brought to a trusted pastor or mature believer.$gs$),
  ('6d44f15f-c56c-5e50-9862-705e1223b1f3', '3fb22436-f60b-51f6-b035-3bb3a37ffa4e', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• Assurance rests first on God’s promise and Christ’s work, not on emotional intensity.
