insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('ec5afb0e-502e-5a99-a651-8bf6690b3ebd', '3fb22436-f60b-51f6-b035-3bb3a37ffa4e', 'memory_verse', $gs${"reference":"1 John 5:13","text":"These things I have written to you who believe in the name of the Son of God, that you may know that you have eternal life.","translation":""}$gs$::jsonb, 0, true, false),
  ('2c657713-eb8b-51a8-87b0-c6c238acce25', '3fb22436-f60b-51f6-b035-3bb3a37ffa4e', 'paragraph', $gs${"text":"Definition and simple explanation\n\nAssurance is confidence that God has given eternal life to those who trust in Christ. Its foundation is God’s promise and Jesus’ finished work, not the changing strength of our emotions. Feelings can rise and fall, especially during stress or hardship."}$gs$::jsonb, 1, false, false),
  ('3a062888-48e2-5606-bd30-5b7718c05a1f', '3fb22436-f60b-51f6-b035-3bb3a37ffa4e', 'paragraph', $gs${"text":"What this means and why it matters\n\nThe New Testament also describes changes that accompany genuine faith, such as growing love, obedience, and the Spirit’s fruit. These are signs of God’s work, not a way to earn His acceptance. Persistent distress or serious questions can be brought to a trusted pastor or mature believer."}$gs$::jsonb, 2, false, false),
  ('8a25e876-83e9-5a61-999e-75f67b788a17', '3fb22436-f60b-51f6-b035-3bb3a37ffa4e', 'paragraph', $gs${"text":"Important things to remember\n\n• Assurance rests first on God’s promise and Christ’s work, not on emotional intensity.\n• Evidence of growth is encouraging, but it is not a system for earning salvation."}$gs$::jsonb, 3, false, false),
  ('ae7d69ba-3755-5913-b8d5-672cbc268e19', '3fb22436-f60b-51f6-b035-3bb3a37ffa4e', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('1063f7de-4eee-56c2-a398-092b182ef1d4', '3fb22436-f60b-51f6-b035-3bb3a37ffa4e', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Assurance Rests on God’s Promise, Not Feelings”?"}$gs$::jsonb, 5, true, true),
  ('2361fa1f-9285-5c54-a86e-7f51ebd4b418', '3fb22436-f60b-51f6-b035-3bb3a37ffa4e', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('7021d4b9-1e95-53c5-b258-3ab01665cbff', '3fb22436-f60b-51f6-b035-3bb3a37ffa4e', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
