insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('48e0b98f-6507-5954-aabe-9fea6af0927b', 'b02d9c47-fa95-536b-bc96-8918ca0c49b6', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$This lesson focuses on The Finished Work of Christ. Begin by reading the key Bible passage in its full context. Notice who is speaking, who is being addressed, what problem or question is being discussed, and what the passage teaches about God and people. The lesson title gives the subject, but the passage provides the foundation for understanding it.$gs$),
  ('3f2168af-3228-5957-9f9f-ec1a11a95ff6', 'b02d9c47-fa95-536b-bc96-8918ca0c49b6', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$The main point is to understand how this teaching connects with the Christian life and the wider message of Scripture. Avoid drawing conclusions from one sentence alone. Compare the passage with other relevant parts of the Bible, ask what a faithful response looks like, and remember that Christian growth is a process of learning to trust and obey God.$gs$),
  ('eb2c7f33-f48f-561e-94c3-000d03568bc8', 'b02d9c47-fa95-536b-bc96-8918ca0c49b6', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
