insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('75ef641f-d480-5b1f-9d88-1b60e5154a98', 'a55cfb8c-46a8-56ec-9a47-140846ad50c2', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$Growing love for others is an important sign of Christian life. The Bible describes love not merely as warm feelings but as practical care, patience, truthfulness, generosity, and willingness to serve.$gs$),
  ('e98f1071-7021-5178-b34c-a766ee181dd1', 'a55cfb8c-46a8-56ec-9a47-140846ad50c2', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$Christians do not love perfectly, and growth takes time. When we fail, we confess it and seek to make things right. Love is evidence of God’s work in us, not a way to buy His favour.$gs$),
  ('916a2e34-09ad-5d8f-826d-0d3f766e7883', 'a55cfb8c-46a8-56ec-9a47-140846ad50c2', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
