insert into public.p2p_assignment_questions (id, assignment_id, question, display_order) values
  ('1d8d6567-616d-5f77-b6c4-0e59d3b2f2f2', 'e000fcef-95ca-566c-a87f-08bef113566e', $gs$Define the main idea in the lesson “Growing Love for Others” using simple language.$gs$, 1),
  ('78c62bf8-c113-53e2-a16f-661ca95b6afc', 'e000fcef-95ca-566c-a87f-08bef113566e', $gs$What does the key Bible passage teach about God, people, or the Christian life?$gs$, 2),
  ('cbcef8ea-fd10-55cb-99cd-9c341b5a270e', 'e000fcef-95ca-566c-a87f-08bef113566e', $gs$Explain why this teaching matters. Give one reason from the lesson.$gs$, 3),
  ('a3854d71-62ea-5caf-b18c-eebc458bd394', 'e000fcef-95ca-566c-a87f-08bef113566e', $gs$Give one practical example of how someone could respond to this teaching.$gs$, 4)
insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('69af6544-2ba8-55f3-b3ff-73424a6ecff2', 'a55cfb8c-46a8-56ec-9a47-140846ad50c2', 'memory_verse', $gs${"reference":"1 John 3:14","text":"We know that we have passed from death to life, because we love the brethren.","translation":""}$gs$::jsonb, 0, true, false),
  ('bbbf9f27-2dd1-52f2-86ac-f9e6fb8fa009', 'a55cfb8c-46a8-56ec-9a47-140846ad50c2', 'paragraph', $gs${"text":"Definition and simple explanation\n\nGrowing love for others is an important sign of Christian life. The Bible describes love not merely as warm feelings but as practical care, patience, truthfulness, generosity, and willingness to serve."}$gs$::jsonb, 1, false, false),
  ('d5b27a84-fbf5-5636-9294-dc092696b816', 'a55cfb8c-46a8-56ec-9a47-140846ad50c2', 'paragraph', $gs${"text":"What this means and why it matters\n\nChristians do not love perfectly, and growth takes time. When we fail, we confess it and seek to make things right. Love is evidence of God’s work in us, not a way to buy His favour."}$gs$::jsonb, 2, false, false),
  ('979bee2c-fa8c-5061-8875-ef5656a9b499', 'a55cfb8c-46a8-56ec-9a47-140846ad50c2', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('52b631d2-452c-5711-8d96-758a9af58c58', 'a55cfb8c-46a8-56ec-9a47-140846ad50c2', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('350f5a83-85e4-5553-9a54-4d38282d4154', 'a55cfb8c-46a8-56ec-9a47-140846ad50c2', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Growing Love for Others”?"}$gs$::jsonb, 5, true, true),
  ('065fc118-8f93-58c9-9b07-feef2af92e5e', 'a55cfb8c-46a8-56ec-9a47-140846ad50c2', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('c612cd15-5147-5dd9-8c11-51d836c85637', 'a55cfb8c-46a8-56ec-9a47-140846ad50c2', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('d7eab6f0-a13f-503b-ad56-50334c45c248', 'a55cfb8c-46a8-56ec-9a47-140846ad50c2', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “Growing Love for Others” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
insert into public.p2p_lessons (id, module_id, title, subtitle, order_index, status, estimated_minutes, published_at, version)
