insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('c5be5bcf-be91-5892-a5a9-fea3cd7bc1ef', '634969f1-dfaa-5c30-8e2a-964a6ca12dff', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$The fruit of the Spirit describes qualities the Holy Spirit grows in a believer: love, joy, peace, patience, kindness, goodness, faithfulness, gentleness, and self-control. These qualities develop over time as we walk with God.$gs$),
  ('8a086550-c964-5271-9128-843fee6a362c', '634969f1-dfaa-5c30-8e2a-964a6ca12dff', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$Fruit is not produced by pretending or by trying to impress people. We cooperate with the Spirit by trusting God, obeying Scripture, turning from sin, and remaining connected to Christ.$gs$),
  ('4831301b-53e3-55f7-b2da-fed4b95f07f8', '634969f1-dfaa-5c30-8e2a-964a6ca12dff', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
insert into public.p2p_reflection_questions (id, lesson_id, question, display_order) values
  ('d05e11d7-3dfc-591d-93f7-39da9c7cb78a', '634969f1-dfaa-5c30-8e2a-964a6ca12dff', $gs$In your own words, what is the main point of “The Spirit’s Fruit Beginning to Grow”?$gs$, 1),
  ('2836afa6-0391-56dd-bade-7a17aca73bda', '634969f1-dfaa-5c30-8e2a-964a6ca12dff', $gs$What part of this teaching is easiest for you to understand, and what part would you like to discuss further?$gs$, 2),
  ('e0bb0dd5-0f56-5c2c-a6ce-4ec0b45d48da', '634969f1-dfaa-5c30-8e2a-964a6ca12dff', $gs$How could this truth shape one attitude or action in your life this week?$gs$, 3)
