  ('e08778e6-03b5-5524-9bf7-47ba7583b081', 'b66c8166-c619-5236-8ebb-fa5200510849', $gs$Define the main idea in the lesson “The Spirit’s Fruit Beginning to Grow” using simple language.$gs$, 1),
  ('f1ec6b59-6ce5-58cb-b8ca-923856000841', 'b66c8166-c619-5236-8ebb-fa5200510849', $gs$What does the key Bible passage teach about God, people, or the Christian life?$gs$, 2),
  ('28d89e38-5677-5ec8-8c4d-68b91c649835', 'b66c8166-c619-5236-8ebb-fa5200510849', $gs$Explain why this teaching matters. Give one reason from the lesson.$gs$, 3),
  ('fcf7c46a-12e8-567e-ac16-e2a4997e2747', 'b66c8166-c619-5236-8ebb-fa5200510849', $gs$Give one practical example of how someone could respond to this teaching.$gs$, 4)
insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('9ec19fcc-569c-599b-af77-d89717f76d59', '634969f1-dfaa-5c30-8e2a-964a6ca12dff', 'memory_verse', $gs${"reference":"Galatians 5:22","text":"But the fruit of the Spirit is love, joy, peace, longsuffering, kindness, goodness, faithfulness.","translation":""}$gs$::jsonb, 0, true, false),
  ('f20447f8-92b2-51ed-b847-58d449148b4d', '634969f1-dfaa-5c30-8e2a-964a6ca12dff', 'paragraph', $gs${"text":"Definition and simple explanation\n\nThe fruit of the Spirit describes qualities the Holy Spirit grows in a believer: love, joy, peace, patience, kindness, goodness, faithfulness, gentleness, and self-control. These qualities develop over time as we walk with God."}$gs$::jsonb, 1, false, false),
  ('f9feb9d7-b0bd-5626-9204-41cec7b49673', '634969f1-dfaa-5c30-8e2a-964a6ca12dff', 'paragraph', $gs${"text":"What this means and why it matters\n\nFruit is not produced by pretending or by trying to impress people. We cooperate with the Spirit by trusting God, obeying Scripture, turning from sin, and remaining connected to Christ."}$gs$::jsonb, 2, false, false),
  ('06ee7444-2ef6-59ff-9ebd-b71ae891c209', '634969f1-dfaa-5c30-8e2a-964a6ca12dff', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('a9e3db7c-8422-588c-a43e-5f3bf6de1f3a', '634969f1-dfaa-5c30-8e2a-964a6ca12dff', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader. Common Obstacles to Assurance"}$gs$::jsonb, 4, false, false),
  ('765ec9c2-468b-569e-b731-bf845cf80938', '634969f1-dfaa-5c30-8e2a-964a6ca12dff', 'reflection_question', $gs${"question":"In your own words, what is the main point of “The Spirit’s Fruit Beginning to Grow”?"}$gs$::jsonb, 5, true, true),
  ('5f78cf15-c2fd-5a97-a413-749b7983c4b3', '634969f1-dfaa-5c30-8e2a-964a6ca12dff', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('9a375967-4be9-585c-8c12-dafdfd820864', '634969f1-dfaa-5c30-8e2a-964a6ca12dff', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('58e171eb-dcf8-5fe0-9f04-d1e0bfd8e9d3', '634969f1-dfaa-5c30-8e2a-964a6ca12dff', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “The Spirit’s Fruit Beginning to Grow” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
