insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('5d553238-46c6-5153-b4cc-ba78bf057d5a', 'a47bf485-9984-531a-afe1-97f941e5dba9', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$Assurance is confidence that God has given eternal life to those who trust in Christ. Its foundation is God’s promise and Jesus’ finished work, not the changing strength of our emotions. Feelings can rise and fall, especially during stress or hardship.$gs$),
  ('72ff0e75-4b31-527c-969d-db72470197be', 'a47bf485-9984-531a-afe1-97f941e5dba9', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$The New Testament also describes changes that accompany genuine faith, such as growing love, obedience, and the Spirit’s fruit. These are signs of God’s work, not a way to earn His acceptance. Persistent distress or serious questions can be brought to a trusted pastor or mature believer.$gs$),
  ('1d823150-222e-5782-a9ee-45b06bfd708b', 'a47bf485-9984-531a-afe1-97f941e5dba9', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• Assurance rests first on God’s promise and Christ’s work, not on emotional intensity.
