insert into public.p2p_assignment_questions (id, assignment_id, question, display_order) values
  ('188f5899-435e-5113-bc15-81e570326158', 'fbdf2e37-7e84-5fb5-9b70-697200efdaf6', $gs$Define the main idea in the lesson “Doubt During Difficult Seasons” using simple language.$gs$, 1),
  ('90b59f5e-e78c-5217-954b-ac7ed19b889f', 'fbdf2e37-7e84-5fb5-9b70-697200efdaf6', $gs$What does the key Bible passage teach about God, people, or the Christian life?$gs$, 2),
  ('e4a62100-03db-5454-958d-b14729b13d07', 'fbdf2e37-7e84-5fb5-9b70-697200efdaf6', $gs$Explain why this teaching matters. Give one reason from the lesson.$gs$, 3),
  ('3be02e33-24cd-551f-9820-d96a42cdc066', 'fbdf2e37-7e84-5fb5-9b70-697200efdaf6', $gs$Give one practical example of how someone could respond to this teaching.$gs$, 4)
insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('fdc8f27a-3185-53d3-bce1-092e56477106', 'a47bf485-9984-531a-afe1-97f941e5dba9', 'memory_verse', $gs${"reference":"Job 13:15","text":"Though He slay me, yet will I trust Him.","translation":""}$gs$::jsonb, 0, true, false),
  ('a7cc4f3d-3b2c-5c1c-9153-bf0b1cadb0bd', 'a47bf485-9984-531a-afe1-97f941e5dba9', 'paragraph', $gs${"text":"Definition and simple explanation\n\nAssurance is confidence that God has given eternal life to those who trust in Christ. Its foundation is God’s promise and Jesus’ finished work, not the changing strength of our emotions. Feelings can rise and fall, especially during stress or hardship."}$gs$::jsonb, 1, false, false),
  ('de150145-6bc3-5141-8e39-962256a417f3', 'a47bf485-9984-531a-afe1-97f941e5dba9', 'paragraph', $gs${"text":"What this means and why it matters\n\nThe New Testament also describes changes that accompany genuine faith, such as growing love, obedience, and the Spirit’s fruit. These are signs of God’s work, not a way to earn His acceptance. Persistent distress or serious questions can be brought to a trusted pastor or mature believer."}$gs$::jsonb, 2, false, false),
  ('410236d0-c4ff-59bc-bfcf-e7f28afc582c', 'a47bf485-9984-531a-afe1-97f941e5dba9', 'paragraph', $gs${"text":"Important things to remember\n\n• Assurance rests first on God’s promise and Christ’s work, not on emotional intensity.\n• Evidence of growth is encouraging, but it is not a system for earning salvation."}$gs$::jsonb, 3, false, false),
  ('f029b502-0e28-51dc-a4a8-bf956df9a6a9', 'a47bf485-9984-531a-afe1-97f941e5dba9', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('b90177b6-9cb5-5415-8d04-02f8f63362bb', 'a47bf485-9984-531a-afe1-97f941e5dba9', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Doubt During Difficult Seasons”?"}$gs$::jsonb, 5, true, true),
  ('22079de1-631a-5040-b7b1-53fa590e25b0', 'a47bf485-9984-531a-afe1-97f941e5dba9', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('5ba79f98-2101-5aa9-9ec1-2492eb9fb4fb', 'a47bf485-9984-531a-afe1-97f941e5dba9', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('aef54b2e-e00d-592d-a71e-b391dd754b93', 'a47bf485-9984-531a-afe1-97f941e5dba9', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “Doubt During Difficult Seasons” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
