insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('11b099df-9c16-51c1-90dc-81f7e8bd3cc6', '708a0bde-50bd-5033-9c4e-81994f7d581b', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$This lesson focuses on Comparing Your Journey to Others. Begin by reading the key Bible passage in its full context. Notice who is speaking, who is being addressed, what problem or question is being discussed, and what the passage teaches about God and people. The lesson title gives the subject, but the passage provides the foundation for understanding it.$gs$),
  ('3d605bed-a1df-503a-bfee-8e2cbff5b9da', '708a0bde-50bd-5033-9c4e-81994f7d581b', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$The main point is to understand how this teaching connects with the Christian life and the wider message of Scripture. Avoid drawing conclusions from one sentence alone. Compare the passage with other relevant parts of the Bible, ask what a faithful response looks like, and remember that Christian growth is a process of learning to trust and obey God.$gs$),
  ('d1575c02-2eea-52d4-9e52-d7415479abf0', '708a0bde-50bd-5033-9c4e-81994f7d581b', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
