insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('79d52db2-3b1e-5b0a-9758-0fdfe9539267', '708a0bde-50bd-5033-9c4e-81994f7d581b', 'memory_verse', $gs${"reference":"John 21:22","text":"But what is that to you? You follow Me.","translation":""}$gs$::jsonb, 0, true, false),
  ('3c3af8da-2f42-5c46-a7f5-63408f140577', '708a0bde-50bd-5033-9c4e-81994f7d581b', 'paragraph', $gs${"text":"Definition and simple explanation\n\nThis lesson focuses on Comparing Your Journey to Others. Begin by reading the key Bible passage in its full context. Notice who is speaking, who is being addressed, what problem or question is being discussed, and what the passage teaches about God and people. The lesson title gives the subject, but the passage provides the foundation for understanding it."}$gs$::jsonb, 1, false, false),
  ('180ea781-1e91-5761-b25f-f4c7d1fce189', '708a0bde-50bd-5033-9c4e-81994f7d581b', 'paragraph', $gs${"text":"What this means and why it matters\n\nThe main point is to understand how this teaching connects with the Christian life and the wider message of Scripture. Avoid drawing conclusions from one sentence alone. Compare the passage with other relevant parts of the Bible, ask what a faithful response looks like, and remember that Christian growth is a process of learning to trust and obey God."}$gs$::jsonb, 2, false, false),
  ('b69a57a2-eb9c-50ed-9889-32aa6828ba9b', '708a0bde-50bd-5033-9c4e-81994f7d581b', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('81de3a56-6c85-5fc3-b536-1791dc329552', '708a0bde-50bd-5033-9c4e-81994f7d581b', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('db02c03e-93a6-5bdd-a2c0-e663090da6a3', '708a0bde-50bd-5033-9c4e-81994f7d581b', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Comparing Your Journey to Others”?"}$gs$::jsonb, 5, true, true),
  ('b8add335-0db8-53c1-80a9-0b6185196302', '708a0bde-50bd-5033-9c4e-81994f7d581b', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
