  ('e4b8d5b3-c533-5f22-bf0b-f1b1e52cc161', 'e899da2f-3823-5c81-b995-5e9597d20596', 'memory_verse', $gs${"reference":"Romans 7:15","text":"For what I am doing, I do not understand. For what I will to do, that I do not practice.","translation":""}$gs$::jsonb, 0, true, false),
  ('f2f3a6ca-b506-5236-8a9b-a0eb2b9f81e4', 'e899da2f-3823-5c81-b995-5e9597d20596', 'paragraph', $gs${"text":"Definition and simple explanation\n\nThis lesson focuses on Confusing Struggle With Sin for Loss of Salvation. Begin by reading the key Bible passage in its full context. Notice who is speaking, who is being addressed, what problem or question is being discussed, and what the passage teaches about God and people. The lesson title gives the subject, but the passage provides the foundation for understanding it."}$gs$::jsonb, 1, false, false),
  ('dda8b1fa-b959-5df8-85d1-15d6a729c9bf', 'e899da2f-3823-5c81-b995-5e9597d20596', 'paragraph', $gs${"text":"What this means and why it matters\n\nThe main point is to understand how this teaching connects with the Christian life and the wider message of Scripture. Avoid drawing conclusions from one sentence alone. Compare the passage with other relevant parts of the Bible, ask what a faithful response looks like, and remember that Christian growth is a process of learning to trust and obey God."}$gs$::jsonb, 2, false, false),
  ('66fd71ee-d466-5026-b308-0ca79a7e69d1', 'e899da2f-3823-5c81-b995-5e9597d20596', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('c8863af6-be23-5a3a-a80a-49641d049ff7', 'e899da2f-3823-5c81-b995-5e9597d20596', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader. Living in Confident Assurance"}$gs$::jsonb, 4, false, false),
  ('283ba620-6dad-520d-a0c1-f8830a67d6ea', 'e899da2f-3823-5c81-b995-5e9597d20596', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Confusing Struggle With Sin for Loss of Salvation”?"}$gs$::jsonb, 5, true, true),
  ('986d7a13-0cea-554c-8553-6643aadcaf04', 'e899da2f-3823-5c81-b995-5e9597d20596', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
