insert into public.p2p_lessons (id, module_id, title, subtitle, order_index, status, estimated_minutes, published_at, version)
insert into public.p2p_scriptures (id, lesson_id, reference, verse, display_order)
insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('5152b7d1-179d-5af1-9d2c-65a6fd4379bb', '35cb6865-0ff9-57e7-85ec-2ccc87ab39a7', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$Assurance is confidence that God has given eternal life to those who trust in Christ. Its foundation is God’s promise and Jesus’ finished work, not the changing strength of our emotions. Feelings can rise and fall, especially during stress or hardship.$gs$),
  ('9e0a6064-8e0d-5118-b859-3f956b62db5b', '35cb6865-0ff9-57e7-85ec-2ccc87ab39a7', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$The New Testament also describes changes that accompany genuine faith, such as growing love, obedience, and the Spirit’s fruit. These are signs of God’s work, not a way to earn His acceptance. Persistent distress or serious questions can be brought to a trusted pastor or mature believer.$gs$),
  ('76a704ae-de93-55dc-9a29-204a3467ce43', '35cb6865-0ff9-57e7-85ec-2ccc87ab39a7', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• Assurance rests first on God’s promise and Christ’s work, not on emotional intensity.
