insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('304be410-24f4-5467-8629-eb54dd73ca4b', '35cb6865-0ff9-57e7-85ec-2ccc87ab39a7', 'memory_verse', $gs${"reference":"Romans 15:4","text":"For whatever things were written before were written for our learning, that we through the patience and comfort of the Scriptures might have hope.","translation":""}$gs$::jsonb, 0, true, false),
  ('d193fbc6-8ed3-5420-8047-23c262ee4bd6', '35cb6865-0ff9-57e7-85ec-2ccc87ab39a7', 'paragraph', $gs${"text":"Definition and simple explanation\n\nAssurance is confidence that God has given eternal life to those who trust in Christ. Its foundation is God’s promise and Jesus’ finished work, not the changing strength of our emotions. Feelings can rise and fall, especially during stress or hardship."}$gs$::jsonb, 1, false, false),
  ('7a3612eb-6a2f-5fc1-b99d-4fde303080a1', '35cb6865-0ff9-57e7-85ec-2ccc87ab39a7', 'paragraph', $gs${"text":"What this means and why it matters\n\nThe New Testament also describes changes that accompany genuine faith, such as growing love, obedience, and the Spirit’s fruit. These are signs of God’s work, not a way to earn His acceptance. Persistent distress or serious questions can be brought to a trusted pastor or mature believer."}$gs$::jsonb, 2, false, false),
  ('fa818135-436c-5c21-b99b-75ed7eba42a2', '35cb6865-0ff9-57e7-85ec-2ccc87ab39a7', 'paragraph', $gs${"text":"Important things to remember\n\n• Assurance rests first on God’s promise and Christ’s work, not on emotional intensity.\n• Evidence of growth is encouraging, but it is not a system for earning salvation."}$gs$::jsonb, 3, false, false),
  ('95a71571-0c40-53c8-8fd6-33c92383908e', '35cb6865-0ff9-57e7-85ec-2ccc87ab39a7', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('f23371d6-4102-5a1e-9a8e-6bc6866ea7a7', '35cb6865-0ff9-57e7-85ec-2ccc87ab39a7', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Returning to Scripture When Doubt Arises”?"}$gs$::jsonb, 5, true, true),
  ('5d28c893-592b-5a2f-b427-fb3017ef3144', '35cb6865-0ff9-57e7-85ec-2ccc87ab39a7', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('f3045f9b-8c5b-5852-a1e5-755a0094f8a6', '35cb6865-0ff9-57e7-85ec-2ccc87ab39a7', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('a1f6afc7-1b2a-51ba-825f-b3bd2edd912d', '35cb6865-0ff9-57e7-85ec-2ccc87ab39a7', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “Returning to Scripture When Doubt Arises” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
