insert into public.p2p_assignment_questions (id, assignment_id, question, display_order) values
  ('e5c1ff5c-75ab-5d73-befa-565f7a4a5e12', '8376fc6c-993d-507e-8f5a-6a8001bddae9', $gs$Define the main idea in the lesson “A Lifetime of Settled Confidence” using simple language.$gs$, 1),
  ('4d5495b2-c963-519c-9046-28d85a462d08', '8376fc6c-993d-507e-8f5a-6a8001bddae9', $gs$What does the key Bible passage teach about God, people, or the Christian life?$gs$, 2),
  ('527bd3a6-0fa7-503e-b225-0d6d6e6ba5eb', '8376fc6c-993d-507e-8f5a-6a8001bddae9', $gs$Explain why this teaching matters. Give one reason from the lesson.$gs$, 3),
  ('66cea1a4-08e5-549f-ad77-3048cd6b526a', '8376fc6c-993d-507e-8f5a-6a8001bddae9', $gs$Give one practical example of how someone could respond to this teaching.$gs$, 4)
insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('3769ac93-3875-5d9c-a4b8-e773758e27a9', '9328d66a-ad45-5237-8437-e4a74d1006c2', 'memory_verse', $gs${"reference":"1 John 5:13","text":"These things I have written to you who believe in the name of the Son of God, that you may know that you have eternal life.","translation":""}$gs$::jsonb, 0, true, false),
  ('4ee0e032-16ba-52b9-9465-407caf9db981', '9328d66a-ad45-5237-8437-e4a74d1006c2', 'paragraph', $gs${"text":"Definition and simple explanation\n\nAssurance is confidence that God has given eternal life to those who trust in Christ. Its foundation is God’s promise and Jesus’ finished work, not the changing strength of our emotions. Feelings can rise and fall, especially during stress or hardship."}$gs$::jsonb, 1, false, false),
  ('bf7c377f-34bb-5b9b-8f26-c0ced075fed6', '9328d66a-ad45-5237-8437-e4a74d1006c2', 'paragraph', $gs${"text":"What this means and why it matters\n\nThe New Testament also describes changes that accompany genuine faith, such as growing love, obedience, and the Spirit’s fruit. These are signs of God’s work, not a way to earn His acceptance. Persistent distress or serious questions can be brought to a trusted pastor or mature believer."}$gs$::jsonb, 2, false, false),
  ('fb633ee3-3cae-503b-b24a-8b3acc55beb4', '9328d66a-ad45-5237-8437-e4a74d1006c2', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('4940d6fc-4fa2-5978-a0c0-2acae73730ae', '9328d66a-ad45-5237-8437-e4a74d1006c2', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('fe717a26-6472-510d-8e09-4a205f8cc8c4', '9328d66a-ad45-5237-8437-e4a74d1006c2', 'reflection_question', $gs${"question":"In your own words, what is the main point of “A Lifetime of Settled Confidence”?"}$gs$::jsonb, 5, true, true),
  ('3cf62bba-20ae-52f3-89bf-fa14be1472aa', '9328d66a-ad45-5237-8437-e4a74d1006c2', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('881eba59-a4f7-5b4d-a8af-60e4df2a0e4e', '9328d66a-ad45-5237-8437-e4a74d1006c2', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('ccc7c83a-8249-518b-be4a-41b11b44ce1a', '9328d66a-ad45-5237-8437-e4a74d1006c2', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “A Lifetime of Settled Confidence” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
