insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('6857c6c1-87a1-581b-a0c4-f2d6fd84db9f', 'a5bff507-dce4-5aeb-bca0-fd8372ea72a8', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$This lesson focuses on A Public Declaration of Faith. Begin by reading the key Bible passage in its full context. Notice who is speaking, who is being addressed, what problem or question is being discussed, and what the passage teaches about God and people. The lesson title gives the subject, but the passage provides the foundation for understanding it.$gs$),
  ('9fc3310b-b020-51b8-802f-665ad7521175', 'a5bff507-dce4-5aeb-bca0-fd8372ea72a8', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$The main point is to understand how this teaching connects with the Christian life and the wider message of Scripture. Avoid drawing conclusions from one sentence alone. Compare the passage with other relevant parts of the Bible, ask what a faithful response looks like, and remember that Christian growth is a process of learning to trust and obey God.$gs$),
  ('e6a7378a-d83b-51a4-a5b2-c162d2e31767', 'a5bff507-dce4-5aeb-bca0-fd8372ea72a8', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
