  ('5617d037-19e5-521b-a54e-25ed923e978f', 'a5bff507-dce4-5aeb-bca0-fd8372ea72a8', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
