insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('3c9b42df-152f-51e8-93a5-9560967a85b0', '65dd1cb7-90cc-5431-a959-28a240ca42ec', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$The resurrection means that Jesus physically rose from the dead. The Christian faith is not based only on the memory of a wise teacher or on the idea that His influence continued. The apostles proclaimed that the risen Jesus was seen by witnesses.$gs$),
  ('49ec1a9d-abc8-5fe4-ac2a-c65bb11659c6', '65dd1cb7-90cc-5431-a959-28a240ca42ec', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$The resurrection shows that death did not defeat Jesus and that His saving work is accepted. It gives believers hope that death is not the end and that those who belong to Christ will also be raised.$gs$),
  ('89c36489-1f44-5482-88b7-dba13a2061cc', '65dd1cb7-90cc-5431-a959-28a240ca42ec', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
