insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('7211b1f2-e2be-5a0a-92ed-32059090ed6a', '65dd1cb7-90cc-5431-a959-28a240ca42ec', 'memory_verse', $gs${"reference":"Romans 6:4","text":"Therefore we were buried with Him through baptism into death, that just as Christ was raised from the dead… we also should walk in newness of life.","translation":""}$gs$::jsonb, 0, true, false),
  ('96c3ed80-12e3-50a0-b286-64c493bce2e7', '65dd1cb7-90cc-5431-a959-28a240ca42ec', 'paragraph', $gs${"text":"Definition and simple explanation\n\nThe resurrection means that Jesus physically rose from the dead. The Christian faith is not based only on the memory of a wise teacher or on the idea that His influence continued. The apostles proclaimed that the risen Jesus was seen by witnesses."}$gs$::jsonb, 1, false, false),
  ('09b9b31a-e09c-5de5-87a3-720da972e90e', '65dd1cb7-90cc-5431-a959-28a240ca42ec', 'paragraph', $gs${"text":"What this means and why it matters\n\nThe resurrection shows that death did not defeat Jesus and that His saving work is accepted. It gives believers hope that death is not the end and that those who belong to Christ will also be raised."}$gs$::jsonb, 2, false, false),
  ('931a7db3-e751-571b-b60c-e6906b93dd50', '65dd1cb7-90cc-5431-a959-28a240ca42ec', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('eb20f0ef-db53-5dd5-b6ee-285451c6d51c', '65dd1cb7-90cc-5431-a959-28a240ca42ec', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('563b6e70-5fb7-53eb-a0f3-531048f9b96e', '65dd1cb7-90cc-5431-a959-28a240ca42ec', 'reflection_question', $gs${"question":"In your own words, what is the main point of “A Picture of Death, Burial, and Resurrection”?"}$gs$::jsonb, 5, true, true),
  ('c5c72612-0f15-5c95-8abe-2c49d86b3f43', '65dd1cb7-90cc-5431-a959-28a240ca42ec', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('02d04ad3-2d74-5e58-9a2d-c5d7d396a07d', '65dd1cb7-90cc-5431-a959-28a240ca42ec', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('c690eb0d-8dce-5523-ba21-dadf54a9308b', '65dd1cb7-90cc-5431-a959-28a240ca42ec', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “A Picture of Death, Burial, and Resurrection” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
