  ('d23bc31b-ef9c-56a3-a8a2-d17c6e1a2128', '6494c5fc-bc71-5690-a039-ee8636466ced', 'paragraph', $gs${"text":"What this means and why it matters\n\nThe main point is to understand how this teaching connects with the Christian life and the wider message of Scripture. Avoid drawing conclusions from one sentence alone. Compare the passage with other relevant parts of the Bible, ask what a faithful response looks like, and remember that Christian growth is a process of learning to trust and obey God."}$gs$::jsonb, 2, false, false),
  ('b5599f48-e210-55fd-8758-a2fa74061f4c', '6494c5fc-bc71-5690-a039-ee8636466ced', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('31076111-f764-5d96-bbcb-34535c6ab86e', '6494c5fc-bc71-5690-a039-ee8636466ced', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader. Baptism in the Pattern of Scripture"}$gs$::jsonb, 4, false, false),
  ('1cd0264d-e869-55b5-b478-5f6437ed1be8', '6494c5fc-bc71-5690-a039-ee8636466ced', 'reflection_question', $gs${"question":"In your own words, what is the main point of “An Act of Obedience, Not a Means of Salvation”?"}$gs$::jsonb, 5, true, true),
  ('f91f449a-2768-5750-8c4a-e35011dd4fae', '6494c5fc-bc71-5690-a039-ee8636466ced', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('6aa23fcf-5cdc-5a0e-b745-59057540db04', '6494c5fc-bc71-5690-a039-ee8636466ced', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('cd3e21e7-f6b0-5993-836f-f8018461824c', '6494c5fc-bc71-5690-a039-ee8636466ced', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “An Act of Obedience, Not a Means of Salvation” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
