insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('552db31a-3914-5c6f-868b-738e3209f93f', 'e2f299b0-566c-512c-bdbd-d2359aebab8c', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$Christian baptism is an act Jesus commanded and an outward sign connected with a believer’s identification with Him. It publicly points to faith in Christ and, especially in the picture of going under and rising from the water, to sharing in the pattern of His death and resurrection.$gs$),
  ('8a3a6d7e-bd60-5046-8480-1f0dbb15fe7f', 'e2f299b0-566c-512c-bdbd-d2359aebab8c', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$Baptism is important obedience, but this curriculum teaches that salvation is by God’s grace through faith, not earned by the act of baptism. Christians and churches differ on some details of baptism’s meaning and practice; learners should study Scripture and speak with their church leaders.$gs$),
  ('cb348c91-4304-5e97-a554-c4856f1955b8', 'e2f299b0-566c-512c-bdbd-d2359aebab8c', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• Baptism is a serious act of Christian obedience and public identification with Christ.
