  ('9cf04768-a351-5910-8bf6-fb8d81c1eef3', 'e2f299b0-566c-512c-bdbd-d2359aebab8c', 'memory_verse', $gs${"reference":"Matthew 3:13","text":"Then Jesus came from Galilee to John at the Jordan to be baptized by him.","translation":""}$gs$::jsonb, 0, true, false),
  ('c8c4a9c7-fcfa-52a7-9751-03c351099884', 'e2f299b0-566c-512c-bdbd-d2359aebab8c', 'paragraph', $gs${"text":"Definition and simple explanation\n\nChristian baptism is an act Jesus commanded and an outward sign connected with a believer’s identification with Him. It publicly points to faith in Christ and, especially in the picture of going under and rising from the water, to sharing in the pattern of His death and resurrection."}$gs$::jsonb, 1, false, false),
  ('f4e5228d-9de9-599f-aae4-cddbe4c4cd63', 'e2f299b0-566c-512c-bdbd-d2359aebab8c', 'paragraph', $gs${"text":"What this means and why it matters\n\nBaptism is important obedience, but this curriculum teaches that salvation is by God’s grace through faith, not earned by the act of baptism. Christians and churches differ on some details of baptism’s meaning and practice; learners should study Scripture and speak with their church leaders."}$gs$::jsonb, 2, false, false),
  ('6f1f7abb-d48b-5de6-9f98-21551e9df5da', 'e2f299b0-566c-512c-bdbd-d2359aebab8c', 'paragraph', $gs${"text":"Important things to remember\n\n• Baptism is a serious act of Christian obedience and public identification with Christ.\n• This curriculum distinguishes baptism from the basis of salvation; consult your church’s teaching for its understanding of baptism’s practice."}$gs$::jsonb, 3, false, false),
  ('766c49bf-8c5f-59b3-bc4f-c27f4815c5df', 'e2f299b0-566c-512c-bdbd-d2359aebab8c', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('149f0cba-477e-5ab7-b3d5-a456d58b1e95', 'e2f299b0-566c-512c-bdbd-d2359aebab8c', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Jesus’s Own Baptism”?"}$gs$::jsonb, 5, true, true),
  ('848516a3-45fb-55b0-8e7b-cb794da7b805', 'e2f299b0-566c-512c-bdbd-d2359aebab8c', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
