insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('98bc20e8-1897-5de6-9554-35d1f14a71ac', 'abe2fc6f-441c-55d9-99e8-31ce0906f176', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$This lesson focuses on Counting It a Privilege, Not a Formality. Begin by reading the key Bible passage in its full context. Notice who is speaking, who is being addressed, what problem or question is being discussed, and what the passage teaches about God and people. The lesson title gives the subject, but the passage provides the foundation for understanding it.$gs$),
  ('e630dcd4-cb8a-5fa9-98df-8115622c89b1', 'abe2fc6f-441c-55d9-99e8-31ce0906f176', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$The main point is to understand how this teaching connects with the Christian life and the wider message of Scripture. Avoid drawing conclusions from one sentence alone. Compare the passage with other relevant parts of the Bible, ask what a faithful response looks like, and remember that Christian growth is a process of learning to trust and obey God.$gs$),
  ('762bedad-52f8-50f8-8cfa-8ebe3b38641e', 'abe2fc6f-441c-55d9-99e8-31ce0906f176', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
