insert into public.p2p_assignment_questions (id, assignment_id, question, display_order) values
  ('89dae8fc-5894-5e62-abac-2df311abd193', '93aaa106-deab-57e8-b345-e822fa6411d4', $gs$Define the main idea in the lesson “Counting It a Privilege, Not a Formality” using simple language.$gs$, 1),
  ('3f7acba7-58dd-5162-9961-f6adc4ef49be', '93aaa106-deab-57e8-b345-e822fa6411d4', $gs$What does the key Bible passage teach about God, people, or the Christian life?$gs$, 2),
  ('20921299-247e-5a1d-99bd-473e36b7d682', '93aaa106-deab-57e8-b345-e822fa6411d4', $gs$Explain why this teaching matters. Give one reason from the lesson.$gs$, 3),
  ('9ff5e1c7-8777-551e-ba18-c519628bb057', '93aaa106-deab-57e8-b345-e822fa6411d4', $gs$Give one practical example of how someone could respond to this teaching.$gs$, 4)
insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('040ef0a3-67f7-5ec4-a8c9-03a563c47f5d', 'abe2fc6f-441c-55d9-99e8-31ce0906f176', 'memory_verse', $gs${"reference":"Matthew 3:11","text":"I indeed baptize you with water unto repentance, but He who is coming after me is mightier than I.","translation":""}$gs$::jsonb, 0, true, false),
  ('0897e376-abef-5d89-9c73-a74f21a2ba39', 'abe2fc6f-441c-55d9-99e8-31ce0906f176', 'paragraph', $gs${"text":"Definition and simple explanation\n\nThis lesson focuses on Counting It a Privilege, Not a Formality. Begin by reading the key Bible passage in its full context. Notice who is speaking, who is being addressed, what problem or question is being discussed, and what the passage teaches about God and people. The lesson title gives the subject, but the passage provides the foundation for understanding it."}$gs$::jsonb, 1, false, false),
  ('c14ee643-871a-51b0-a9fd-e353c94f190b', 'abe2fc6f-441c-55d9-99e8-31ce0906f176', 'paragraph', $gs${"text":"What this means and why it matters\n\nThe main point is to understand how this teaching connects with the Christian life and the wider message of Scripture. Avoid drawing conclusions from one sentence alone. Compare the passage with other relevant parts of the Bible, ask what a faithful response looks like, and remember that Christian growth is a process of learning to trust and obey God."}$gs$::jsonb, 2, false, false),
  ('40f54d68-2b27-57af-a3d2-18b1575a17a6', 'abe2fc6f-441c-55d9-99e8-31ce0906f176', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('036e3351-4cc7-5164-b235-f00325c546a1', 'abe2fc6f-441c-55d9-99e8-31ce0906f176', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('9d35f1f4-5ba6-5bef-89ae-82e0875a3f54', 'abe2fc6f-441c-55d9-99e8-31ce0906f176', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Counting It a Privilege, Not a Formality”?"}$gs$::jsonb, 5, true, true),
  ('4183191c-63bb-59d7-bd90-26f4506eb704', 'abe2fc6f-441c-55d9-99e8-31ce0906f176', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('02539e04-3069-52ea-9e06-bcd250cb1c39', 'abe2fc6f-441c-55d9-99e8-31ce0906f176', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('601916a1-9dee-5dcd-80db-4c0b26e5fe82', 'abe2fc6f-441c-55d9-99e8-31ce0906f176', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “Counting It a Privilege, Not a Formality” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
