  ('d7a61cef-e898-5bd1-8ca1-ace98d3b0490', '45b029ee-4616-5c09-ac4f-ee5189c4edc3', 'memory_verse', $gs${"reference":"Romans 6:4","text":"That just as Christ was raised from the dead by the glory of the Father, even so we also should walk in newness of life.","translation":""}$gs$::jsonb, 0, true, false),
  ('f414fda5-f5da-58be-b8db-012f4cc8069c', '45b029ee-4616-5c09-ac4f-ee5189c4edc3', 'paragraph', $gs${"text":"Definition and simple explanation\n\nThis lesson focuses on Walking in Newness of Life. Begin by reading the key Bible passage in its full context. Notice who is speaking, who is being addressed, what problem or question is being discussed, and what the passage teaches about God and people. The lesson title gives the subject, but the passage provides the foundation for understanding it."}$gs$::jsonb, 1, false, false),
  ('6609bfc9-d504-5cdb-9bad-be2af12b60e5', '45b029ee-4616-5c09-ac4f-ee5189c4edc3', 'paragraph', $gs${"text":"What this means and why it matters\n\nThe main point is to understand how this teaching connects with the Christian life and the wider message of Scripture. Avoid drawing conclusions from one sentence alone. Compare the passage with other relevant parts of the Bible, ask what a faithful response looks like, and remember that Christian growth is a process of learning to trust and obey God."}$gs$::jsonb, 2, false, false),
  ('95be53b5-2f09-5073-a3ff-d3687188ed7d', '45b029ee-4616-5c09-ac4f-ee5189c4edc3', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('cd03f245-2c07-5249-847c-f85d22564117', '45b029ee-4616-5c09-ac4f-ee5189c4edc3', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('217be8ab-a811-5175-bf78-ba3d668ba400', '45b029ee-4616-5c09-ac4f-ee5189c4edc3', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Walking in Newness of Life”?"}$gs$::jsonb, 5, true, true),
  ('b3d082b2-ed5f-52ef-a2d6-040690ad67a1', '45b029ee-4616-5c09-ac4f-ee5189c4edc3', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('f4b4ac48-0caf-5f3a-bcf8-9729827b0561', '45b029ee-4616-5c09-ac4f-ee5189c4edc3', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('19951f44-3906-5795-9433-c6c807d5bc45', '45b029ee-4616-5c09-ac4f-ee5189c4edc3', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “Walking in Newness of Life” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
