insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('4765a0b2-cc8e-56f0-bc2d-3c6e2934ec55', '6650ff12-2106-5dc0-a7db-056dd1b4b19a', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$Christian baptism is an act Jesus commanded and an outward sign connected with a believer’s identification with Him. It publicly points to faith in Christ and, especially in the picture of going under and rising from the water, to sharing in the pattern of His death and resurrection.$gs$),
  ('1a203987-b521-5a12-928c-258a37fca062', '6650ff12-2106-5dc0-a7db-056dd1b4b19a', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$Baptism is important obedience, but this curriculum teaches that salvation is by God’s grace through faith, not earned by the act of baptism. Christians and churches differ on some details of baptism’s meaning and practice; learners should study Scripture and speak with their church leaders.$gs$),
  ('055aa889-0c45-5798-8fe8-25703d398578', '6650ff12-2106-5dc0-a7db-056dd1b4b19a', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• Baptism is a serious act of Christian obedience and public identification with Christ.
