  ('a6d1bfbe-16fc-5c57-a88c-18370435d04a', '6650ff12-2106-5dc0-a7db-056dd1b4b19a', 'memory_verse', $gs${"reference":"Romans 6:6","text":"Knowing this, that our old man was crucified with Him, that the body of sin might be done away with.","translation":""}$gs$::jsonb, 0, true, false),
  ('17d07454-e3d2-5289-9bbc-2af238c94986', '6650ff12-2106-5dc0-a7db-056dd1b4b19a', 'paragraph', $gs${"text":"Definition and simple explanation\n\nChristian baptism is an act Jesus commanded and an outward sign connected with a believer’s identification with Him. It publicly points to faith in Christ and, especially in the picture of going under and rising from the water, to sharing in the pattern of His death and resurrection."}$gs$::jsonb, 1, false, false),
  ('726967a2-9eb3-5f11-9ef9-fcfd13ebb079', '6650ff12-2106-5dc0-a7db-056dd1b4b19a', 'paragraph', $gs${"text":"What this means and why it matters\n\nBaptism is important obedience, but this curriculum teaches that salvation is by God’s grace through faith, not earned by the act of baptism. Christians and churches differ on some details of baptism’s meaning and practice; learners should study Scripture and speak with their church leaders."}$gs$::jsonb, 2, false, false),
  ('99374a75-95d1-5bbe-9bb0-ad5115927830', '6650ff12-2106-5dc0-a7db-056dd1b4b19a', 'paragraph', $gs${"text":"Important things to remember\n\n• Baptism is a serious act of Christian obedience and public identification with Christ.\n• This curriculum distinguishes baptism from the basis of salvation; consult your church’s teaching for its understanding of baptism’s practice."}$gs$::jsonb, 3, false, false),
  ('dbb0c7a5-52a8-51c8-928c-1df95f4168ad', '6650ff12-2106-5dc0-a7db-056dd1b4b19a', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('4812a86b-14b7-5fd8-b489-ff85eaad7530', '6650ff12-2106-5dc0-a7db-056dd1b4b19a', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Remembering Your Baptism in Times of Temptation”?"}$gs$::jsonb, 5, true, true),
  ('34759fc3-3e0f-549a-a856-7526e02308c1', '6650ff12-2106-5dc0-a7db-056dd1b4b19a', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('b7c6bd76-f10a-50dd-9987-aa471929fd38', '6650ff12-2106-5dc0-a7db-056dd1b4b19a', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('c4397340-3b70-5747-8664-1902e19b2117', '6650ff12-2106-5dc0-a7db-056dd1b4b19a', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “Remembering Your Baptism in Times of Temptation” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
