insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('de6810c6-ef76-5fd0-80c0-85479578034c', 'ca6741b0-ce37-5e3e-869f-b31a9dbe145e', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$A disciple is a learner who follows Jesus. Discipleship means listening to His teaching, trusting Him, obeying Him, and becoming more like Him over a lifetime. It is not reserved for pastors or unusually committed Christians; every believer is called to follow Jesus.$gs$),
  ('698bee2c-aad2-5422-96a7-1290cb2eeeb3', 'ca6741b0-ce37-5e3e-869f-b31a9dbe145e', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$Following Jesus has a cost because His priorities may challenge our comfort, habits, and relationships. Jesus does not call us to earn salvation through effort; He calls those who belong to Him to live out their faith with loyalty and perseverance.$gs$),
  ('e9ce3b76-f59e-547b-8fbf-c48adebbe6cd', 'ca6741b0-ce37-5e3e-869f-b31a9dbe145e', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
