insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('4d58da6c-7668-5dab-9727-d15a6845fdf2', '2fa98eab-67b0-5353-95a0-b97bc4cb491d', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$A disciple is a learner who follows Jesus. Discipleship means listening to His teaching, trusting Him, obeying Him, and becoming more like Him over a lifetime. It is not reserved for pastors or unusually committed Christians; every believer is called to follow Jesus.$gs$),
  ('cc51143c-b5cf-5c8d-a751-b348a3e41ef6', '2fa98eab-67b0-5353-95a0-b97bc4cb491d', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$Following Jesus has a cost because His priorities may challenge our comfort, habits, and relationships. Jesus does not call us to earn salvation through effort; He calls those who belong to Him to live out their faith with loyalty and perseverance.$gs$),
  ('6d59c3c9-478d-566e-bc4a-75a780795185', '2fa98eab-67b0-5353-95a0-b97bc4cb491d', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
