insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('208886c6-748e-5021-b830-a14b913f9458', '2fa98eab-67b0-5353-95a0-b97bc4cb491d', 'memory_verse', $gs${"reference":"Luke 14:26","text":"If anyone comes to Me and does not hate his father and mother, wife and children… yes, and his own life also, he cannot be My disciple.","translation":""}$gs$::jsonb, 0, true, false),
  ('e7f80f7f-017c-5ce0-a07a-a0631b212017', '2fa98eab-67b0-5353-95a0-b97bc4cb491d', 'paragraph', $gs${"text":"Definition and simple explanation\n\nA disciple is a learner who follows Jesus. Discipleship means listening to His teaching, trusting Him, obeying Him, and becoming more like Him over a lifetime. It is not reserved for pastors or unusually committed Christians; every believer is called to follow Jesus."}$gs$::jsonb, 1, false, false),
  ('b9c26cd3-e06e-52dc-8433-acfbb34a5e3c', '2fa98eab-67b0-5353-95a0-b97bc4cb491d', 'paragraph', $gs${"text":"What this means and why it matters\n\nFollowing Jesus has a cost because His priorities may challenge our comfort, habits, and relationships. Jesus does not call us to earn salvation through effort; He calls those who belong to Him to live out their faith with loyalty and perseverance."}$gs$::jsonb, 2, false, false),
  ('935f4a4f-c571-578c-b751-e8e5d83846b3', '2fa98eab-67b0-5353-95a0-b97bc4cb491d', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('47dbc147-6a8d-5f9f-abd0-7c7e7adca5d5', '2fa98eab-67b0-5353-95a0-b97bc4cb491d', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('25f34fa2-c952-528e-84f8-162bcc537e36', '2fa98eab-67b0-5353-95a0-b97bc4cb491d', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Discipleship Is Costly”?"}$gs$::jsonb, 5, true, true),
  ('eef45a2d-f95e-51a0-b056-1473b30c71dc', '2fa98eab-67b0-5353-95a0-b97bc4cb491d', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('bdb6f923-b6ea-525c-ac14-82a073be5d6d', '2fa98eab-67b0-5353-95a0-b97bc4cb491d', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('0ac72370-896e-5aeb-afce-4949b292e12c', '2fa98eab-67b0-5353-95a0-b97bc4cb491d', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “Discipleship Is Costly” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
