insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('7a638638-f2ae-572c-812f-5b0dcd6d95d0', '37000578-2b79-5f07-a301-44dfc2e8683f', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$The Bible is God’s written Word and gives believers truth, correction, encouragement, and guidance. Reading it regularly is like receiving nourishment: it helps us know God, understand the gospel, and learn how to live.$gs$),
  ('5f5eb436-6ee8-5cfd-b48f-b03d104495c0', '37000578-2b79-5f07-a301-44dfc2e8683f', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$Start with a manageable portion, read carefully, ask what the passage says about God and people, and consider how to respond. The goal is not to finish pages quickly but to understand and obey what God has said.$gs$),
  ('5ccaf141-5173-5d14-a707-3bcea27a7ece', '37000578-2b79-5f07-a301-44dfc2e8683f', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
