insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('b9eb377f-eff4-5068-9097-e40ded64dfa6', 'a49b5900-7799-5e58-bb5d-6c2de8af24f9', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$Prayer is speaking and listening to God in dependence, worship, confession, thanksgiving, and request. It is not a performance or a way to force God to give us what we want. Jesus teaches His followers to pray honestly and trust their Father.$gs$),
  ('9457cd70-331e-52e5-aed8-504d724a13a2', 'a49b5900-7799-5e58-bb5d-6c2de8af24f9', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$A steady prayer life can include set times as well as brief prayers throughout the day. When words are difficult, use Scripture to guide your prayers and remember that prayer is about relationship with God, not impressive language.$gs$),
  ('822c688b-2a68-5869-bfc0-a4d4243316a3', 'a49b5900-7799-5e58-bb5d-6c2de8af24f9', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
