  ('94f1c5aa-b7cb-58bc-8f3b-79f852a61faf', 'b16d52de-a341-5391-ae3f-eef4dfa09c95', $gs$Give one practical example of how someone could respond to this teaching.$gs$, 4)
insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('693c790a-6fc2-50b0-b919-24ab4e9a0575', 'a49b5900-7799-5e58-bb5d-6c2de8af24f9', 'memory_verse', $gs${"reference":"1 Thessalonians 5:17","text":"Pray without ceasing.","translation":""}$gs$::jsonb, 0, true, false),
  ('88e1977b-fe9b-581c-acd8-c9e3f0a7b07e', 'a49b5900-7799-5e58-bb5d-6c2de8af24f9', 'paragraph', $gs${"text":"Definition and simple explanation\n\nPrayer is speaking and listening to God in dependence, worship, confession, thanksgiving, and request. It is not a performance or a way to force God to give us what we want. Jesus teaches His followers to pray honestly and trust their Father."}$gs$::jsonb, 1, false, false),
  ('a7515c41-88a2-5460-8692-d66a03ab654a', 'a49b5900-7799-5e58-bb5d-6c2de8af24f9', 'paragraph', $gs${"text":"What this means and why it matters\n\nA steady prayer life can include set times as well as brief prayers throughout the day. When words are difficult, use Scripture to guide your prayers and remember that prayer is about relationship with God, not impressive language."}$gs$::jsonb, 2, false, false),
  ('ef275f47-686e-52f8-af60-378d33991832', 'a49b5900-7799-5e58-bb5d-6c2de8af24f9', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('fbf0340c-27e0-5218-a860-4dbd8cee7699', 'a49b5900-7799-5e58-bb5d-6c2de8af24f9', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('ba4e6674-d668-581a-b660-9ee53e9054f4', 'a49b5900-7799-5e58-bb5d-6c2de8af24f9', 'reflection_question', $gs${"question":"In your own words, what is the main point of “A Consistent Life of Prayer”?"}$gs$::jsonb, 5, true, true),
  ('151f1b96-646e-5e67-b780-2bd7246aa0f5', 'a49b5900-7799-5e58-bb5d-6c2de8af24f9', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('3af05a6f-acde-5fca-a3b5-7a1f9f20e1d3', 'a49b5900-7799-5e58-bb5d-6c2de8af24f9', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('cddc4c07-7d98-5896-b153-ec39c05d453e', 'a49b5900-7799-5e58-bb5d-6c2de8af24f9', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “A Consistent Life of Prayer” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
