insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('7b6e9e4b-cf54-5e1d-a3ce-366bf0db273c', '60b4dd36-660a-5277-a401-4b286615f89c', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$The local church is a community of believers who gather to worship, learn Scripture, pray, serve, encourage one another, and share the Lord’s Supper and baptism according to their practice. Christian faith is personal, but it is not meant to be lived in isolation.$gs$),
  ('3d67f0ed-3e2c-52ef-bbea-ce8dd650fff5', '60b4dd36-660a-5277-a401-4b286615f89c', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$Commitment to a healthy church gives opportunities to grow and to care for others. Churches are made of imperfect people, so commitment includes patience, forgiveness, wise boundaries, and seeking help when serious problems arise.$gs$),
  ('e57bee84-cdd8-5ed2-a736-7dd21ee21ed0', '60b4dd36-660a-5277-a401-4b286615f89c', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
