insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('2a664fcf-0597-53d4-aa69-15e3a2dd1071', 'bf8d8cdd-9c1a-52fd-8aa4-9c996529155e', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$A disciple is a learner who follows Jesus. Discipleship means listening to His teaching, trusting Him, obeying Him, and becoming more like Him over a lifetime. It is not reserved for pastors or unusually committed Christians; every believer is called to follow Jesus.$gs$),
  ('9d2c4761-0bc2-554a-b7c4-582b5ac01ed7', 'bf8d8cdd-9c1a-52fd-8aa4-9c996529155e', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$Following Jesus has a cost because His priorities may challenge our comfort, habits, and relationships. Jesus does not call us to earn salvation through effort; He calls those who belong to Him to live out their faith with loyalty and perseverance.$gs$),
  ('b67291d8-0c3d-5a29-a05b-a0f8b4a4c3bc', 'bf8d8cdd-9c1a-52fd-8aa4-9c996529155e', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
