  ('739d205f-0eb7-544f-982d-22eaf069549a', 'bf8d8cdd-9c1a-52fd-8aa4-9c996529155e', 'paragraph', $gs${"text":"Definition and simple explanation\n\nA disciple is a learner who follows Jesus. Discipleship means listening to His teaching, trusting Him, obeying Him, and becoming more like Him over a lifetime. It is not reserved for pastors or unusually committed Christians; every believer is called to follow Jesus."}$gs$::jsonb, 1, false, false),
  ('0f942877-daf7-5ced-a77a-dbd4442254e6', 'bf8d8cdd-9c1a-52fd-8aa4-9c996529155e', 'paragraph', $gs${"text":"What this means and why it matters\n\nFollowing Jesus has a cost because His priorities may challenge our comfort, habits, and relationships. Jesus does not call us to earn salvation through effort; He calls those who belong to Him to live out their faith with loyalty and perseverance."}$gs$::jsonb, 2, false, false),
  ('0b8f3269-5c48-535a-a523-524762d93c30', 'bf8d8cdd-9c1a-52fd-8aa4-9c996529155e', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('beb7900e-ff0c-58ba-b858-e2ddd1bf762e', 'bf8d8cdd-9c1a-52fd-8aa4-9c996529155e', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('4302901e-8a5c-5535-87b9-9dfeba75ff97', 'bf8d8cdd-9c1a-52fd-8aa4-9c996529155e', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Being Discipled by Someone Further Along”?"}$gs$::jsonb, 5, true, true),
  ('9c5a6e61-1c12-5fc7-8f89-213199b5e351', 'bf8d8cdd-9c1a-52fd-8aa4-9c996529155e', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('a702139d-8a86-5c1b-8e96-a8b8045dea47', 'bf8d8cdd-9c1a-52fd-8aa4-9c996529155e', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('52a3468c-84e7-5a34-b726-db3426a5f183', 'bf8d8cdd-9c1a-52fd-8aa4-9c996529155e', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “Being Discipled by Someone Further Along” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
