insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('91b661c5-0b32-56b7-9077-8160a79ddcd5', 'f810a9b6-eb5a-50d7-aba9-f4481ffd4fa6', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$This lesson focuses on Discipling Someone Behind You. Begin by reading the key Bible passage in its full context. Notice who is speaking, who is being addressed, what problem or question is being discussed, and what the passage teaches about God and people. The lesson title gives the subject, but the passage provides the foundation for understanding it.$gs$),
  ('5183e6a4-acf7-530b-bee4-7c4a6ceaecdb', 'f810a9b6-eb5a-50d7-aba9-f4481ffd4fa6', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$The main point is to understand how this teaching connects with the Christian life and the wider message of Scripture. Avoid drawing conclusions from one sentence alone. Compare the passage with other relevant parts of the Bible, ask what a faithful response looks like, and remember that Christian growth is a process of learning to trust and obey God.$gs$),
  ('844a9247-558a-5482-a7f8-220e50955774', 'f810a9b6-eb5a-50d7-aba9-f4481ffd4fa6', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
