insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('79b5cefc-0e84-5b70-b1ad-19ff43f66d90', '9c6e051f-fa70-59c1-a37b-98ed51ae18b7', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$This lesson focuses on Iron Sharpening Iron in Community. Begin by reading the key Bible passage in its full context. Notice who is speaking, who is being addressed, what problem or question is being discussed, and what the passage teaches about God and people. The lesson title gives the subject, but the passage provides the foundation for understanding it.$gs$),
  ('e3434ee4-f158-5626-9c84-5ee45dd99b46', '9c6e051f-fa70-59c1-a37b-98ed51ae18b7', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$The main point is to understand how this teaching connects with the Christian life and the wider message of Scripture. Avoid drawing conclusions from one sentence alone. Compare the passage with other relevant parts of the Bible, ask what a faithful response looks like, and remember that Christian growth is a process of learning to trust and obey God.$gs$),
  ('982e107d-2508-56f1-a688-4098b4a49486', '9c6e051f-fa70-59c1-a37b-98ed51ae18b7', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
