  ('10ea3483-95a2-5df5-836f-f2f9cabe436a', '9c6e051f-fa70-59c1-a37b-98ed51ae18b7', 'memory_verse', $gs${"reference":"Proverbs 27:17","text":"As iron sharpens iron, so a man sharpens the countenance of his friend.","translation":""}$gs$::jsonb, 0, true, false),
  ('d1086277-b140-5bcd-a34b-d15e3bdb3c8e', '9c6e051f-fa70-59c1-a37b-98ed51ae18b7', 'paragraph', $gs${"text":"Definition and simple explanation\n\nThis lesson focuses on Iron Sharpening Iron in Community. Begin by reading the key Bible passage in its full context. Notice who is speaking, who is being addressed, what problem or question is being discussed, and what the passage teaches about God and people. The lesson title gives the subject, but the passage provides the foundation for understanding it."}$gs$::jsonb, 1, false, false),
  ('c837a9f3-96ba-56b1-a0dc-251bad8f2607', '9c6e051f-fa70-59c1-a37b-98ed51ae18b7', 'paragraph', $gs${"text":"What this means and why it matters\n\nThe main point is to understand how this teaching connects with the Christian life and the wider message of Scripture. Avoid drawing conclusions from one sentence alone. Compare the passage with other relevant parts of the Bible, ask what a faithful response looks like, and remember that Christian growth is a process of learning to trust and obey God."}$gs$::jsonb, 2, false, false),
  ('80b56f83-2042-5a77-b830-ffb880d44e9d', '9c6e051f-fa70-59c1-a37b-98ed51ae18b7', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('57a51e62-34ba-5cc4-95d0-5ef844e245ea', '9c6e051f-fa70-59c1-a37b-98ed51ae18b7', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader. Living as a Disciple for Life"}$gs$::jsonb, 4, false, false),
  ('c95fcc51-e1d1-5e51-af6e-a5e0239919ab', '9c6e051f-fa70-59c1-a37b-98ed51ae18b7', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Iron Sharpening Iron in Community”?"}$gs$::jsonb, 5, true, true),
  ('0607a62a-0ecb-5ea7-ac16-f039733f7242', '9c6e051f-fa70-59c1-a37b-98ed51ae18b7', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
