insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('e07aaa5c-a26e-5a25-837f-7fd298a78926', '969b543e-7afe-5b55-ac56-3c30c1addcd0', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$The fruit of the Spirit describes qualities the Holy Spirit grows in a believer: love, joy, peace, patience, kindness, goodness, faithfulness, gentleness, and self-control. These qualities develop over time as we walk with God.$gs$),
  ('9183d1a9-17c3-54d7-afba-961cc2b8198c', '969b543e-7afe-5b55-ac56-3c30c1addcd0', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$Fruit is not produced by pretending or by trying to impress people. We cooperate with the Spirit by trusting God, obeying Scripture, turning from sin, and remaining connected to Christ.$gs$),
  ('68ab227e-58b2-5494-8b77-d27ac694448c', '969b543e-7afe-5b55-ac56-3c30c1addcd0', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
