  ('17c97453-dd38-52ac-afdc-5cabd540732d', '969b543e-7afe-5b55-ac56-3c30c1addcd0', 'paragraph', $gs${"text":"What this means and why it matters\n\nFruit is not produced by pretending or by trying to impress people. We cooperate with the Spirit by trusting God, obeying Scripture, turning from sin, and remaining connected to Christ."}$gs$::jsonb, 2, false, false),
  ('41ffaf98-a93a-5d05-ba43-9038472d6639', '969b543e-7afe-5b55-ac56-3c30c1addcd0', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('b1127ffb-014d-522f-9bfc-e038f3cb9696', '969b543e-7afe-5b55-ac56-3c30c1addcd0', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader."}$gs$::jsonb, 4, false, false),
  ('96cadb25-7c40-5819-ad45-379bc7d9b59c', '969b543e-7afe-5b55-ac56-3c30c1addcd0', 'reflection_question', $gs${"question":"In your own words, what is the main point of “Bearing Fruit That Remains”?"}$gs$::jsonb, 5, true, true),
  ('6db84993-506c-51f1-a66c-915b04dedac6', '969b543e-7afe-5b55-ac56-3c30c1addcd0', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('6fffc1c6-9074-5748-ac56-fba4326df867', '969b543e-7afe-5b55-ac56-3c30c1addcd0', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('99684c7d-5024-5ec1-a1d7-00b4bd3139dd', '969b543e-7afe-5b55-ac56-3c30c1addcd0', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “Bearing Fruit That Remains” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
