insert into public.p2p_lesson_sections (id, lesson_id, section_order, section_type, title, content) values
  ('771bdf18-60a5-538d-8913-fc5b824d8a69', 'c5c7a446-ac88-5c6b-8b82-3a4530e35f5f', 1, 'teaching', $gs$Definition and simple explanation$gs$, $gs$A disciple is a learner who follows Jesus. Discipleship means listening to His teaching, trusting Him, obeying Him, and becoming more like Him over a lifetime. It is not reserved for pastors or unusually committed Christians; every believer is called to follow Jesus.$gs$),
  ('223b0c1a-9498-5426-a399-5f0e5a75daad', 'c5c7a446-ac88-5c6b-8b82-3a4530e35f5f', 2, 'teaching', $gs$What this means and why it matters$gs$, $gs$Following Jesus has a cost because His priorities may challenge our comfort, habits, and relationships. Jesus does not call us to earn salvation through effort; He calls those who belong to Him to live out their faith with loyalty and perseverance.$gs$),
  ('28fd2da4-925a-50b7-8c20-473bb029391a', 'c5c7a446-ac88-5c6b-8b82-3a4530e35f5f', 3, 'teaching', $gs$Important things to remember$gs$, $gs$• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.
