insert into public.p2p_assignment_questions (id, assignment_id, question, display_order) values
  ('d89bb2f4-2ee1-5047-a409-7286654da29c', '69f4b24b-d10e-5ac0-942b-fa57fe0b4052', $gs$Define the main idea in the lesson “A Lifetime of Following Jesus” using simple language.$gs$, 1),
  ('09fe889d-93ef-5598-b98d-74f83b10b28e', '69f4b24b-d10e-5ac0-942b-fa57fe0b4052', $gs$What does the key Bible passage teach about God, people, or the Christian life?$gs$, 2),
  ('c40fffe1-1861-5396-8b20-15172afbe9a1', '69f4b24b-d10e-5ac0-942b-fa57fe0b4052', $gs$Explain why this teaching matters. Give one reason from the lesson.$gs$, 3),
  ('754e1f94-b88c-5571-baa8-4040a782f603', '69f4b24b-d10e-5ac0-942b-fa57fe0b4052', $gs$Give one practical example of how someone could respond to this teaching.$gs$, 4)
insert into public.p2p_lesson_blocks (id, lesson_id, block_type, content, order_index, is_required, is_submittable) values
  ('95dcca0a-218e-5bb0-bf9f-299d5f52b00b', 'c5c7a446-ac88-5c6b-8b82-3a4530e35f5f', 'memory_verse', $gs${"reference":"Matthew 28:19-20","text":"Go therefore and make disciples of all the nations, baptizing them… teaching them to observe all things that I commanded you.","translation":""}$gs$::jsonb, 0, true, false),
  ('201dff42-43e9-595a-bfc7-47af333e272c', 'c5c7a446-ac88-5c6b-8b82-3a4530e35f5f', 'paragraph', $gs${"text":"Definition and simple explanation\n\nA disciple is a learner who follows Jesus. Discipleship means listening to His teaching, trusting Him, obeying Him, and becoming more like Him over a lifetime. It is not reserved for pastors or unusually committed Christians; every believer is called to follow Jesus."}$gs$::jsonb, 1, false, false),
  ('fc94534d-ed26-50db-b5b3-78ee1bfeb03f', 'c5c7a446-ac88-5c6b-8b82-3a4530e35f5f', 'paragraph', $gs${"text":"What this means and why it matters\n\nFollowing Jesus has a cost because His priorities may challenge our comfort, habits, and relationships. Jesus does not call us to earn salvation through effort; He calls those who belong to Him to live out their faith with loyalty and perseverance."}$gs$::jsonb, 2, false, false),
  ('e112651f-faa1-5307-8e90-ab7777d6bd39', 'c5c7a446-ac88-5c6b-8b82-3a4530e35f5f', 'paragraph', $gs${"text":"Important things to remember\n\n• This teaching should be understood alongside the whole Bible passage, not as an isolated slogan.\n• Do not use this truth to look down on others; respond with humility, love, and dependence on God."}$gs$::jsonb, 3, false, false),
  ('d7bccf57-d27e-51dc-83ec-71b39ddb7d6a', 'c5c7a446-ac88-5c6b-8b82-3a4530e35f5f', 'paragraph', $gs${"text":"Practical application\n\nRead the key passage again in context. Write a short paragraph summarising what you learned, then choose one realistic action that reflects the teaching. If something remains unclear, write down the question and discuss it with your teacher or church leader. TEACHER AND FACILITATOR GUIDE How to teach each lesson • Start by asking learners what they already know about the subject. Do not assume prior theological knowledge. • Read the Bible passage aloud and explain its setting before explaining individual phrases. • Teach the definition first. Then explain the idea in short steps and give a familiar example. • Pause to check understanding. Invite learners to explain the main point in their own words. • Use reflection questions for honest thought, not to shame or pressure learners to disclose private matters. • Use the comprehensive check to identify what needs reteaching. Correct misunderstandings gently and return to the Bible passage. • End with a practical response that is realistic and connected to the lesson. Suggested assessment approach A learner has understood a lesson when they can (1) define its main idea, (2) explain the Bible passage in context, (3) distinguish the teaching from a common misunderstanding, and (4) describe a practical response. For open-ended questions, assess clarity and biblical understanding rather than requiring identical wording. Important editorial note This simplified edition preserves the curriculum’s module and lesson titles and supplies a clear teaching framework for every lesson. Some Christian traditions interpret particular subjects—especially baptism, assurance, and aspects of end-times teaching—differently. Teachers should explain their church’s position fairly, distinguish clear biblical statements from areas of disagreement, and encourage learners to read Scripture in context."}$gs$::jsonb, 4, false, false),
  ('17d0f25d-8629-5caa-96d9-af9b212b85ea', 'c5c7a446-ac88-5c6b-8b82-3a4530e35f5f', 'reflection_question', $gs${"question":"In your own words, what is the main point of “A Lifetime of Following Jesus”?"}$gs$::jsonb, 5, true, true),
  ('6d9d215c-caf2-5c5a-bd0f-a5d29223bb4d', 'c5c7a446-ac88-5c6b-8b82-3a4530e35f5f', 'reflection_question', $gs${"question":"What part of this teaching is easiest for you to understand, and what part would you like to discuss further?"}$gs$::jsonb, 6, true, true),
  ('77367001-8e38-5bce-bc4c-80fff470fd3f', 'c5c7a446-ac88-5c6b-8b82-3a4530e35f5f', 'reflection_question', $gs${"question":"How could this truth shape one attitude or action in your life this week?"}$gs$::jsonb, 7, true, true),
  ('e2db71c9-1b81-52c8-bf6c-86af14705e8c', 'c5c7a446-ac88-5c6b-8b82-3a4530e35f5f', 'assignment', $gs${"title":"Comprehensive Check","instructions":"","due_after_days":7,"questions":[{"question":"Define the main idea in the lesson “A Lifetime of Following Jesus” using simple language."},{"question":"What does the key Bible passage teach about God, people, or the Christian life?"},{"question":"Explain why this teaching matters. Give one reason from the lesson."},{"question":"Give one practical example of how someone could respond to this teaching."}]}$gs$::jsonb, 8, true, true)
